    ('c8e60044-4740-5c23-833e-2497ac608ed1'::uuid, 'Quiz — Le prix environnemental de la croissance', 'Histoire-Géographie', '1re', 'Des ressources et des environnements sous pression en Chine', '61a2a8c7-778c-513f-9ec0-0b05aa08dd3d'::uuid),
    ('3c15938c-e4d5-5164-9a40-05b6894d5abe'::uuid, 'Quiz — Un pays qui a basculé en ville en trente ans', 'Histoire-Géographie', '1re', 'Métropolisation et urbanisation en Chine', '461fd849-a3a0-54dc-9b6a-91c8fbaeecfa'::uuid),
    ('19e3115f-cd3d-5f35-a5ed-98b13f695ce8'::uuid, 'Quiz — La façade maritime, moteur du pays', 'Histoire-Géographie', '1re', 'La littoralisation des espaces productifs en Chine', 'fa66fb53-16b7-512a-8ff4-dcc5c5a85585'::uuid),
    ('c2683946-67f8-55c1-a992-ca9ff0b2172c'::uuid, 'Quiz — Des campagnes vidées, modernisées, inégales', 'Histoire-Géographie', '1re', 'Les espaces ruraux en Chine : continuité ou fragmentation ?', 'f92de399-ff97-54db-9e5c-d92ee0815400'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('29aa8890-d638-582d-b443-126b7fb6baff'::uuid, '2160429b-5698-59e2-b7da-c5762ef87fe9'::uuid, 'Que proclame le tiers état le 17 juin 1789 ?', 'mcq', '["Il se déclare Assemblée nationale","Il proclame la République","Il vote la Constitution civile du clergé","Il abolit la monarchie"]'::jsonb, 0, 'Se dire « Assemblée nationale », c’est affirmer que la souveraineté vient de la nation, pas du roi.', 1),
    ('f993c515-eaf6-5cc6-bdee-7d51e021c934'::uuid, '2160429b-5698-59e2-b7da-c5762ef87fe9'::uuid, 'Que fait la nuit du 4 août 1789 ?', 'mcq', '["Elle abolit les privilèges","Elle exécute le roi","Elle déclare la guerre à l’Autriche","Elle rédige la Constitution"]'::jsonb, 0, 'Les privilèges seigneuriaux et les droits féodaux tombent en une nuit.', 2),
    ('f3785dd9-43d8-59c4-9ee0-115273c2fa01'::uuid, '2160429b-5698-59e2-b7da-c5762ef87fe9'::uuid, 'La Déclaration des droits de l’homme et du citoyen date d’août 1789.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle est adoptée le 26 août 1789 et sert de préambule à la Constitution de 1791.', 3),
    ('0a345219-3b12-55b6-b933-d88e807e9d8f'::uuid, '2160429b-5698-59e2-b7da-c5762ef87fe9'::uuid, 'Quelle distinction la Constitution de 1791 introduit-elle ?', 'mcq', '["Citoyens actifs et citoyens passifs","Nobles et roturiers","Girondins et Montagnards","Français et étrangers"]'::jsonb, 0, 'Le droit de vote dépend d’un cens : l’égalité civile n’est pas encore politique.', 4),
    ('ef71c0cd-4142-59b7-af2f-5a8096023e8d'::uuid, '2160429b-5698-59e2-b7da-c5762ef87fe9'::uuid, 'Quel événement ruine la confiance entre le roi et l’Assemblée ?', 'mcq', '["La fuite à Varennes","La prise de la Bastille","Le serment du Jeu de paume","La journée du 4 août"]'::jsonb, 0, 'En juin 1791, Louis XVI fuit et est arrêté : le roi apparaît comme un traître à la nation.', 5),
    ('dc1b4a52-14e8-5da1-8b36-9353197ffae1'::uuid, '2160429b-5698-59e2-b7da-c5762ef87fe9'::uuid, 'Quand la République est-elle proclamée ?', 'mcq', '["Le 22 septembre 1792","Le 14 juillet 1789","Le 21 janvier 1793","Le 9 thermidor an II"]'::jsonb, 0, 'La Convention proclame la République au lendemain de la victoire de Valmy.', 6),
    ('d8a3b39f-8f33-5eb8-bdf5-ee95c75b18e3'::uuid, '2160429b-5698-59e2-b7da-c5762ef87fe9'::uuid, 'Qu’est-ce que la Terreur (1793-1794) ?', 'mcq', '["Un gouvernement d’exception face à la guerre et à la contre-révolution","Une invasion étrangère","Une famine généralisée","Le retour de la monarchie"]'::jsonb, 0, 'Le Comité de salut public suspend les libertés au nom du salut de la République.', 7),
    ('704200d9-8d4d-51d0-864d-8fac11b42692'::uuid, '2160429b-5698-59e2-b7da-c5762ef87fe9'::uuid, 'Quel régime succède à la Terreur ?', 'mcq', '["Le Directoire","Le Consulat","L’Empire","La Restauration"]'::jsonb, 0, 'Le Directoire (1795-1799) est censitaire et instable : c’est lui que renverse le 18 brumaire.', 8),
    ('3f1f2cf1-05b6-5e9a-a4ba-e6f5055387fb'::uuid, '08a11700-edea-5735-ae75-ba5807307d5e'::uuid, 'Quel coup d’État porte Bonaparte au pouvoir ?', 'mcq', '["Le 18 brumaire an VIII","Le 9 thermidor an II","Le 10 août 1792","Le 2 décembre 1851"]'::jsonb, 0, '9 novembre 1799 : le Directoire est renversé, le Consulat commence.', 1),
    ('a20acefe-d33a-5971-875d-68918a820c4d'::uuid, '08a11700-edea-5735-ae75-ba5807307d5e'::uuid, 'Quel outil Bonaparte utilise-t-il pour faire approuver ses régimes ?', 'mcq', '["Le plébiscite","Le référendum d’initiative populaire","Le tirage au sort","Le vote censitaire"]'::jsonb, 0, 'On répond oui ou non à un pouvoir déjà en place : la question n’est jamais débattue.', 2),
    ('204d25de-5e30-53e3-9eac-3e9b88283b7b'::uuid, '08a11700-edea-5735-ae75-ba5807307d5e'::uuid, 'Le Code civil date de 1804.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il fixe l’égalité devant la loi, la propriété et la famille — et s’exporte dans toute l’Europe.', 3),
    ('908781bc-f029-5e34-acdc-dbc395f3e9c0'::uuid, '08a11700-edea-5735-ae75-ba5807307d5e'::uuid, 'Quel accord Bonaparte signe-t-il avec le pape en 1801 ?', 'mcq', '["Le Concordat","La Constitution civile du clergé","L’édit de tolérance","La loi de séparation"]'::jsonb, 0, 'Le Concordat rétablit la paix religieuse tout en gardant l’État maître des nominations.', 4),
    ('e7a57d55-8b5a-5ffe-9c6b-dfa4c2f968d5'::uuid, '08a11700-edea-5735-ae75-ba5807307d5e'::uuid, 'Qui administre les départements sous le Consulat et l’Empire ?', 'mcq', '["Les préfets","Les intendants","Les gouverneurs","Les députés"]'::jsonb, 0, 'Créés en 1800, les préfets représentent l’État dans chaque département : ils existent toujours.', 5),
    ('7c638ad9-3016-5346-a404-c10e64236151'::uuid, '08a11700-edea-5735-ae75-ba5807307d5e'::uuid, 'Quelle mesure économique vise à asphyxier le Royaume-Uni ?', 'mcq', '["Le Blocus continental","Le Code de commerce","Le franc germinal","Le tarif extérieur commun"]'::jsonb, 0, 'Décrété en 1806, il ferme le continent au commerce britannique — et pèse sur les peuples occupés.', 6),
    ('3cb0e675-f634-587c-b6e0-2d018d080951'::uuid, '08a11700-edea-5735-ae75-ba5807307d5e'::uuid, 'Quel effet inattendu la domination française produit-elle en Europe ?', 'mcq', '["Elle éveille des sentiments nationaux contre elle","Elle fait disparaître les monarchies","Elle unifie l’Europe durablement","Elle supprime les frontières"]'::jsonb, 0, 'Espagne, Allemagne, Russie : l’occupation nourrit les nationalismes du XIXe siècle.', 7),
    ('76dd3cb9-2feb-5752-a8e7-9acc1d60d841'::uuid, '08a11700-edea-5735-ae75-ba5807307d5e'::uuid, 'Quelle campagne brise la Grande Armée ?', 'mcq', '["La campagne de Russie (1812)","La campagne d’Égypte","La bataille d’Austerlitz","Le siège de Toulon"]'::jsonb, 0, 'Sur environ 600 000 hommes engagés, une infime partie revient.', 8),
    ('dd29d3c7-e494-5a39-bfc6-48787b2d57c0'::uuid, '210c4c0b-f602-50b7-8215-1ecc1a214d14'::uuid, 'Que fait le congrès de Vienne (1814-1815) ?', 'mcq', '["Il redessine la carte de l’Europe au nom de la légitimité et de l’équilibre","Il proclame le droit des peuples à disposer d’eux-mêmes","Il crée la Société des Nations","Il abolit la monarchie en Europe"]'::jsonb, 0, 'Les vainqueurs de Napoléon organisent un ordre contre-révolutionnaire.', 1),
    ('e109a6c7-8fe2-53a5-8835-aa7f1b35aca7'::uuid, '210c4c0b-f602-50b7-8215-1ecc1a214d14'::uuid, 'Qui est l’homme fort de l’ordre de Vienne ?', 'mcq', '["Metternich","Cavour","Bismarck","Talleyrand"]'::jsonb, 0, 'Le chancelier autrichien incarne la surveillance des mouvements libéraux et nationaux.', 2),
    ('56daa740-ef47-5911-aab3-0cf1f0c6b312'::uuid, '210c4c0b-f602-50b7-8215-1ecc1a214d14'::uuid, 'Que réclame le nationalisme au XIXe siècle ?', 'mcq', '["Qu’un peuple uni par la langue et l’histoire dispose de son État","Le retour des privilèges","La suppression des frontières","Le pouvoir absolu du roi"]'::jsonb, 0, 'C’est le principe des nationalités, qui bouscule les empires multinationaux.', 3),
    ('9dbfea06-8d3e-54be-8b40-da8d35ed8292'::uuid, '210c4c0b-f602-50b7-8215-1ecc1a214d14'::uuid, 'Quel pays obtient son indépendance en 1830 après une révolution ?', 'mcq', '["La Belgique","L’Italie","L’Allemagne","La Hongrie"]'::jsonb, 0, 'La Belgique se sépare du royaume des Pays-Bas et se dote d’une constitution libérale.', 4),
    ('88d0dd1a-49a0-58fd-ba95-89928cc03706'::uuid, '210c4c0b-f602-50b7-8215-1ecc1a214d14'::uuid, 'Les Trois Glorieuses de juillet 1830 renversent Charles X.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Trois journées d’insurrection parisienne portent Louis-Philippe au pouvoir.', 5),
    ('970c3444-5da7-5a30-b90d-f23298970b4f'::uuid, '210c4c0b-f602-50b7-8215-1ecc1a214d14'::uuid, 'Comment appelle-t-on les révolutions de 1848 en Europe ?', 'mcq', '["Le printemps des peuples","La Sainte-Alliance","La Commune","Le Risorgimento"]'::jsonb, 0, 'De Paris à Budapest, les révolutions s’enchaînent en quelques semaines.', 6),
    ('07c702ef-37d0-5b22-8f3c-4562712b80ec'::uuid, '210c4c0b-f602-50b7-8215-1ecc1a214d14'::uuid, 'Qu’est-ce qu’un suffrage censitaire ?', 'mcq', '["Seuls les citoyens payant un impôt suffisant votent","Tous les hommes votent","Le vote se fait par tirage au sort","Le roi désigne les électeurs"]'::jsonb, 0, 'Sous la monarchie de Juillet, moins de 1 % des Français sont électeurs.', 7),
    ('0fbbc114-2e84-537c-ab5c-a84ac6240f28'::uuid, '210c4c0b-f602-50b7-8215-1ecc1a214d14'::uuid, 'Quelle mobilisation précipite la chute de Louis-Philippe ?', 'mcq', '["La campagne des banquets","La journée des Tuiles","La révolte des canuts","Le coup d’État du 2 décembre"]'::jsonb, 0, 'Interdits, ces banquets réclamaient une réforme électorale : leur interdiction déclenche février 1848.', 8),
    ('fcf0e8df-fd3c-519d-882c-a72a4320af30'::uuid, 'a6b75ad9-7c9f-531c-b9ea-173e550a66c5'::uuid, 'Quelle grande mesure politique la Deuxième République instaure-t-elle en mars 1848 ?', 'mcq', '["Le suffrage universel masculin","Le vote des femmes","Le suffrage censitaire","Le droit de grève"]'::jsonb, 0, 'Le corps électoral passe de 240 000 à environ 9 millions d’hommes.', 1),
    ('7d82ee2e-f6b1-5a82-9b50-ad03e23e3be2'::uuid, 'a6b75ad9-7c9f-531c-b9ea-173e550a66c5'::uuid, 'Quel décret d’avril 1848 abolit l’esclavage dans les colonies françaises ?', 'mcq', '["Le décret Schoelcher","La loi Falloux","Le décret Cavaignac","La loi Le Chapelier"]'::jsonb, 0, 'Victor Schoelcher fait adopter l’abolition définitive le 27 avril 1848.', 2),
    ('05408694-7bf5-525b-aa6e-251753a4a3e1'::uuid, 'a6b75ad9-7c9f-531c-b9ea-173e550a66c5'::uuid, 'Qu’étaient les Ateliers nationaux ?', 'mcq', '["Des chantiers publics ouverts aux chômeurs","Des usines d’État","Des écoles professionnelles","Des ateliers d’artistes"]'::jsonb, 0, 'Leur fermeture déclenche l’insurrection ouvrière de juin 1848.', 3),
    ('c8bbcd5a-3d77-50b8-979c-0a16d7862998'::uuid, 'a6b75ad9-7c9f-531c-b9ea-173e550a66c5'::uuid, 'Les journées de Juin 1848 sont une insurrection ouvrière réprimée par l’armée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le général Cavaignac écrase le soulèvement : la République se coupe du monde ouvrier.', 4),
    ('3b367477-a354-5677-be0a-706f4a251b4e'::uuid, 'a6b75ad9-7c9f-531c-b9ea-173e550a66c5'::uuid, 'Qui est élu président de la République en décembre 1848 ?', 'mcq', '["Louis-Napoléon Bonaparte","Cavaignac","Lamartine","Ledru-Rollin"]'::jsonb, 0, 'Il l’emporte avec près de 74 % des voix, porté par le nom de son oncle.', 5),
    ('b1dd14f6-96c9-5f02-bc67-e5c68dbfd74c'::uuid, 'a6b75ad9-7c9f-531c-b9ea-173e550a66c5'::uuid, 'Que fait la loi de mai 1850 ?', 'mcq', '["Elle restreint le corps électoral","Elle rétablit le suffrage censitaire officiellement","Elle donne le vote aux femmes","Elle abolit la présidence"]'::jsonb, 0, 'Une condition de résidence raye près de 3 millions d’électeurs, surtout ouvriers.', 6),
    ('34563bcb-c250-5360-b7b5-6c5d911642e7'::uuid, 'a6b75ad9-7c9f-531c-b9ea-173e550a66c5'::uuid, 'Quelle est la date du coup d’État de Louis-Napoléon Bonaparte ?', 'mcq', '["Le 2 décembre 1851","Le 18 brumaire an VIII","Le 24 février 1848","Le 4 septembre 1870"]'::jsonb, 0, 'Un an plus tard, jour pour jour, il proclame le Second Empire.', 7),
    ('fcadf3d1-e316-5d71-adf1-202b69039882'::uuid, 'a6b75ad9-7c9f-531c-b9ea-173e550a66c5'::uuid, 'Quelle loi de 1850 renforce la place de l’Église dans l’enseignement ?', 'mcq', '["La loi Falloux","La loi Guizot","La loi Ferry","La loi Combes"]'::jsonb, 0, 'Votée par l’Assemblée conservatrice, elle favorise l’enseignement congréganiste.', 8),
    ('51a983fe-e94d-54ec-8706-f6a79d21d35e'::uuid, 'b104ab0c-9812-5c42-8710-9425f5ccb761'::uuid, 'Qu’est-ce qu’une candidature officielle sous le Second Empire ?', 'mcq', '["Un candidat soutenu et affiché par l’administration","Un candidat désigné par tirage au sort","Un candidat de l’opposition autorisé","Un candidat élu par le Sénat"]'::jsonb, 0, 'Les préfets font campagne pour lui : l’élection reste libre en apparence seulement.', 1),
    ('8c41e0cf-30ab-5f14-8ebc-22bbfde6eafc'::uuid, 'b104ab0c-9812-5c42-8710-9425f5ccb761'::uuid, 'Comment le régime contrôle-t-il la presse ?', 'mcq', '["Par un système d’avertissements pouvant mener à la suspension","Par la nationalisation des journaux","Par l’interdiction totale de la presse","Par une taxe sur le papier"]'::jsonb, 0, 'Deux avertissements et le journal peut être suspendu : l’autocensure fait le reste.', 2),
    ('5748a6dd-7204-5a34-9a9a-93250f1b0c9e'::uuid, 'b104ab0c-9812-5c42-8710-9425f5ccb761'::uuid, 'Le Second Empire supprime le suffrage universel masculin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il le conserve et s’en sert : plébiscites et élections encadrées légitiment le pouvoir personnel.', 3),
    ('1e2786eb-a6e3-5432-82bb-c59c011933ea'::uuid, 'b104ab0c-9812-5c42-8710-9425f5ccb761'::uuid, 'Quelle liberté la loi Ollivier de 1864 accorde-t-elle aux ouvriers ?', 'mcq', '["Le droit de grève","Le droit syndical","Les congés payés","La journée de huit heures"]'::jsonb, 0, 'La grève cesse d’être un délit, mais les syndicats ne sont pas encore autorisés.', 4),
    ('be728467-6af1-503d-9e21-3627045006ec'::uuid, 'b104ab0c-9812-5c42-8710-9425f5ccb761'::uuid, 'Quelle période s’ouvre après 1860 ?', 'mcq', '["L’Empire libéral","La Restauration","La Terreur blanche","L’Ordre moral"]'::jsonb, 0, 'Napoléon III concède des libertés pour élargir sa base politique.', 5),
    ('2ab8f602-ee31-5559-bbbf-071bfc26d2ac'::uuid, 'b104ab0c-9812-5c42-8710-9425f5ccb761'::uuid, 'Quel plébiscite confirme largement Napoléon III quelques mois avant sa chute ?', 'mcq', '["Celui de mai 1870","Celui de 1848","Celui de 1860","Celui de 1875"]'::jsonb, 0, 'Le oui l’emporte massivement : la défaite militaire, elle, sera immédiate.', 6),
    ('904e60e2-8651-531d-a43f-bfe96d10f3f0'::uuid, 'b104ab0c-9812-5c42-8710-9425f5ccb761'::uuid, 'Quelle défaite emporte le Second Empire ?', 'mcq', '["Sedan, le 2 septembre 1870","Waterloo","Sadowa","Solferino"]'::jsonb, 0, 'L’empereur capitule avec son armée ; la République est proclamée deux jours plus tard.', 7),
    ('33ee4917-9c4b-5390-9f45-bc31a17dba4c'::uuid, 'b104ab0c-9812-5c42-8710-9425f5ccb761'::uuid, 'Que sont les « Cinq » de 1857 ?', 'mcq', '["Les cinq députés républicains élus face au régime","Cinq préfets révoqués","Cinq journaux interdits","Cinq ministres libéraux"]'::jsonb, 0, 'Première brèche parlementaire : l’opposition républicaine entre au Corps législatif.', 8),
    ('124f08f0-9fd5-5962-94aa-e11d455bffb5'::uuid, 'dbe4397f-31ed-54cd-bdfe-37d7504a84c0'::uuid, 'De combien de kilomètres le réseau ferré français passe-t-il environ entre 1851 et 1870 ?', 'mcq', '["De 3 000 à près de 17 000 km","De 500 à 3 000 km","De 17 000 à 40 000 km","De 1 000 à 2 000 km"]'::jsonb, 0, 'Le rail multiplie par plus de cinq en vingt ans et unifie le marché national.', 1),
    ('ac9764ba-041d-5f0b-a790-20e311135b79'::uuid, 'dbe4397f-31ed-54cd-bdfe-37d7504a84c0'::uuid, 'Quelle forme a le réseau ferré français ?', 'mcq', '["Une étoile centrée sur Paris","Un quadrillage régulier","Un axe unique nord-sud","Un réseau littoral"]'::jsonb, 0, 'Le tracé en étoile renforce la centralisation du territoire.', 2),
    ('35857d0f-1330-5701-9a60-44b16ae0b40f'::uuid, 'dbe4397f-31ed-54cd-bdfe-37d7504a84c0'::uuid, 'Quelles banques naissent sous le Second Empire ?', 'mcq', '["Le Crédit lyonnais et la Société générale","La Banque de France et la Caisse des dépôts","La BNP et le CIC seuls","La Banque postale"]'::jsonb, 0, 'Fondées en 1863 et 1864, elles drainent l’épargne vers l’industrie.', 3),
    ('09552207-ab35-5e98-b07e-0a78149e1b7a'::uuid, 'dbe4397f-31ed-54cd-bdfe-37d7504a84c0'::uuid, 'Que signe la France avec le Royaume-Uni en 1860 ?', 'mcq', '["Un traité de libre-échange","Une alliance militaire","Un traité de paix","Une union douanière"]'::jsonb, 0, 'Le traité Cobden-Chevalier ouvre le marché français à la concurrence britannique.', 4),
    ('00aff998-12f2-5ee5-859c-eb2ca93b1dca'::uuid, 'dbe4397f-31ed-54cd-bdfe-37d7504a84c0'::uuid, 'Qui transforme Paris sous le Second Empire ?', 'mcq', '["Le préfet Haussmann","L’architecte Garnier","L’ingénieur Eiffel","Le préfet Poubelle"]'::jsonb, 0, 'Percées, égouts, adduction d’eau et gares redessinent la capitale.', 5),
    ('9fe7ce00-3936-5808-9cc0-c0798113927a'::uuid, 'dbe4397f-31ed-54cd-bdfe-37d7504a84c0'::uuid, 'Les travaux d’Haussmann repoussent les ouvriers vers la périphérie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La hausse des loyers dans le centre rénové provoque leur éloignement.', 6),
    ('751c22f1-557a-5142-8fc1-fccbab119995'::uuid, 'dbe4397f-31ed-54cd-bdfe-37d7504a84c0'::uuid, 'Que met en scène une Exposition universelle ?', 'mcq', '["La puissance industrielle et technique du pays","Les productions agricoles régionales","Les collections des musées","Les colonies uniquement"]'::jsonb, 0, 'Paris en accueille deux sous l’Empire, en 1855 et 1867.', 7),
    ('a53913ed-eb11-5031-b1c6-dbb11eb44fe0'::uuid, 'dbe4397f-31ed-54cd-bdfe-37d7504a84c0'::uuid, 'En 1870, la France est déjà majoritairement urbaine et industrielle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La majorité des actifs vit encore de l’agriculture : l’industrialisation est réelle mais inachevée.', 8),
    ('20f31c58-db6e-5765-9746-6f358d75e8f8'::uuid, '19a0210b-5349-526a-9647-923c763812df'::uuid, 'Quelle part de la population française vit à la campagne au milieu du XIXe siècle ?', 'mcq', '["Environ les trois quarts","Environ un quart","La moitié","Un dixième"]'::jsonb, 0, 'La population rurale atteint son maximum historique vers 1851.', 1),
    ('8cee2879-0c36-503e-a81d-c49cc24b9d7c'::uuid, '19a0210b-5349-526a-9647-923c763812df'::uuid, 'Quel fléau ravage le vignoble français à partir de 1863 ?', 'mcq', '["Le phylloxéra","Le mildiou seul","La rouille du blé","La peste bovine"]'::jsonb, 0, 'Ce puceron venu d’Amérique détruit une grande partie des vignes en vingt ans.', 2),
    ('cbb3a424-5132-508a-ba07-42e472b4cbf2'::uuid, '19a0210b-5349-526a-9647-923c763812df'::uuid, 'Comment le chemin de fer transforme-t-il l’agriculture ?', 'mcq', '["Il ouvre les marchés urbains et pousse à la spécialisation","Il fait disparaître les foires","Il supprime les jachères","Il interdit la polyculture"]'::jsonb, 0, 'On produit pour vendre loin, plus seulement pour se nourrir sur place.', 3),
    ('ab90146f-e36c-5668-9836-11d617c11d43'::uuid, '19a0210b-5349-526a-9647-923c763812df'::uuid, 'Qu’est-ce que l’exode rural ?', 'mcq', '["Le départ des campagnes vers les villes","Le retour des citadins à la campagne","Une migration saisonnière des troupeaux","L’émigration vers les colonies"]'::jsonb, 0, 'Il commence lentement sous l’Empire et s’accélère ensuite.', 4),
    ('9c995954-afc2-5300-bccc-6dcb79bed4e7'::uuid, '19a0210b-5349-526a-9647-923c763812df'::uuid, 'Le monde rural du XIXe siècle est resté totalement immobile.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Engrais, machines, spécialisation, ouverture au marché : il change vite, mais sans se vider d’un coup.', 5),
    ('481972fd-90cb-5656-83c1-caf1e7d3d086'::uuid, '19a0210b-5349-526a-9647-923c763812df'::uuid, 'Quels vecteurs diffusent le français dans les campagnes ?', 'mcq', '["L’école, le service militaire et la presse","Uniquement l’Église","Le cinéma","La radio"]'::jsonb, 0, 'Les patois reculent surtout à partir de la Troisième République.', 6),
    ('297ba24b-9e3a-5f75-8d31-d033870f571d'::uuid, '19a0210b-5349-526a-9647-923c763812df'::uuid, 'Comment votent majoritairement les campagnes en décembre 1848 ?', 'mcq', '["Pour Louis-Napoléon Bonaparte","Pour Ledru-Rollin","Pour Cavaignac","Elles s’abstiennent"]'::jsonb, 0, 'Le vote rural fait la victoire du futur empereur.', 7),
    ('c0caadca-bf44-51c7-a0a0-59c09cf59f75'::uuid, '19a0210b-5349-526a-9647-923c763812df'::uuid, 'Que remplace progressivement la jachère ?', 'mcq', '["La rotation des cultures et les engrais","La monoculture obligatoire","La mise en friche","L’élevage extensif seul"]'::jsonb, 0, 'La suppression de la jachère augmente la surface cultivée chaque année.', 8),
    ('801d98f1-6f89-596d-a806-07b8cd2a5c82'::uuid, '593e2d7c-b8f1-5d7e-b14c-bea9007f74ce'::uuid, 'Qui enquête sur la condition ouvrière en 1840 ?', 'mcq', '["Le docteur Villermé","Victor Hugo","Émile Zola","Jules Ferry"]'::jsonb, 0, 'Son tableau de l’état physique et moral des ouvriers marque l’opinion.', 1),
    ('8881d7cc-7866-5b68-af81-ba4ef606940d'::uuid, '593e2d7c-b8f1-5d7e-b14c-bea9007f74ce'::uuid, 'Que limite la loi de 1841 ?', 'mcq', '["Le travail des enfants","La durée du travail des adultes","Le travail de nuit des femmes","Le travail à domicile"]'::jsonb, 0, 'Elle est peu appliquée : aucun corps d’inspection sérieux ne la contrôle.', 2),
    ('167ceeb7-ec93-5a42-9efc-92daf5dbcb2f'::uuid, '593e2d7c-b8f1-5d7e-b14c-bea9007f74ce'::uuid, 'Quelle loi dépénalise la grève en France ?', 'mcq', '["La loi Ollivier de 1864","La loi Le Chapelier","La loi Waldeck-Rousseau","La loi Ferry"]'::jsonb, 0, 'La grève cesse d’être un délit, mais reste encadrée.', 3),
    ('5c51c5b3-3b45-5ee2-ae08-01a0ee32e0c5'::uuid, '593e2d7c-b8f1-5d7e-b14c-bea9007f74ce'::uuid, 'En quelle année les syndicats sont-ils pleinement légalisés ?', 'mcq', '["1884","1864","1871","1848"]'::jsonb, 0, 'La loi Waldeck-Rousseau autorise les syndicats professionnels.', 4),
    ('2a13570b-411a-5d9a-aba8-2e8c5eb65632'::uuid, '593e2d7c-b8f1-5d7e-b14c-bea9007f74ce'::uuid, 'Qu’est-ce que l’AIT fondée en 1864 ?', 'mcq', '["L’Association internationale des travailleurs","Une banque ouvrière","Un parti politique français","Une confédération patronale"]'::jsonb, 0, 'Elle donne un cadre international au mouvement ouvrier naissant.', 5),
    ('1dbc34b2-ae18-5e0b-b3f8-d23a71af9f69'::uuid, '593e2d7c-b8f1-5d7e-b14c-bea9007f74ce'::uuid, 'La Commune de Paris est écrasée lors de la Semaine sanglante de mai 1871.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La répression fait plusieurs milliers de morts et des milliers de déportations.', 6),
    ('703eccf6-a466-5922-bdc1-695f9a3ba7c0'::uuid, '593e2d7c-b8f1-5d7e-b14c-bea9007f74ce'::uuid, 'Que défend Proudhon ?', 'mcq', '["Le mutualisme et l’association ouvrière","La monarchie sociale","Le libre-échange intégral","Le retour à la terre obligatoire"]'::jsonb, 0, 'Il s’oppose à la fois au capitalisme et à l’État centralisateur.', 7),
    ('7a9c2f16-1b00-5493-a0a4-ecb953b74ede'::uuid, '593e2d7c-b8f1-5d7e-b14c-bea9007f74ce'::uuid, 'Pourquoi parle-t-on de « question sociale » ?', 'mcq', '["Parce que la pauvreté ouvrière devient un problème politique à traiter par la loi","Parce que la société refuse d’en parler","Parce qu’elle ne concerne que les campagnes","Parce qu’elle est résolue par la charité"]'::jsonb, 0, 'Elle structure les débats politiques jusqu’au XXe siècle.', 8),
    ('2d689b5c-908f-5976-9e35-0740a11b9684'::uuid, '72d36aba-f8ec-50c4-bc79-7fdddd2f6970'::uuid, 'Qui est le principal artisan politique de l’unité italienne ?', 'mcq', '["Cavour","Bismarck","Metternich","Mazzini seul"]'::jsonb, 0, 'Ministre du Piémont-Sardaigne, il obtient l’alliance française à Plombières.', 1),
    ('fde2f289-49e7-5811-a0a2-ea057289756d'::uuid, '72d36aba-f8ec-50c4-bc79-7fdddd2f6970'::uuid, 'Quelles régions la France obtient-elle en 1860 ?', 'mcq', '["Nice et la Savoie","La Lombardie","La Vénétie","La Corse"]'::jsonb, 0, 'Elles sont rattachées après plébiscites, en échange de l’aide contre l’Autriche.', 2),
    ('41ee7c31-71f3-5d4f-a5a6-016ea7552ae2'::uuid, '72d36aba-f8ec-50c4-bc79-7fdddd2f6970'::uuid, 'Quelle bataille de 1866 assure la domination prussienne sur l’Allemagne ?', 'mcq', '["Sadowa","Solferino","Sedan","Magenta"]'::jsonb, 0, 'La victoire sur l’Autriche écarte Vienne de la future unité allemande.', 3),
    ('8c983c1e-b436-5970-b4a7-0ee23a05257b'::uuid, '72d36aba-f8ec-50c4-bc79-7fdddd2f6970'::uuid, 'Quelle formule résume la méthode de Bismarck ?', 'mcq', '["« Par le fer et par le sang »","« Liberté, égalité, fraternité »","« Le droit des peuples »","« L’Empire, c’est la paix »"]'::jsonb, 0, 'L’unité allemande se fait par la guerre, non par les congrès.', 4),
    ('4cad6660-8cdd-535d-a1cc-a14cc22f234b'::uuid, '72d36aba-f8ec-50c4-bc79-7fdddd2f6970'::uuid, 'Où l’Empire allemand est-il proclamé le 18 janvier 1871 ?', 'mcq', '["Dans la galerie des Glaces de Versailles","À Berlin","À Francfort","À Vienne"]'::jsonb, 0, 'Le lieu choisi humilie la France vaincue.', 5),
    ('34adb470-67c7-56df-9ba8-a5303f5bae9b'::uuid, '72d36aba-f8ec-50c4-bc79-7fdddd2f6970'::uuid, 'Que perd la France au traité de Francfort ?', 'mcq', '["L’Alsace et une grande partie de la Lorraine","La Savoie","Les colonies d’Afrique","La Corse"]'::jsonb, 0, 'S’y ajoute une indemnité de 5 milliards de francs-or.', 6),
    ('5fb38982-e2c4-542c-bd4d-1fb700e811be'::uuid, '72d36aba-f8ec-50c4-bc79-7fdddd2f6970'::uuid, 'La défaite de 1871 nourrit en France l’idée de revanche jusqu’en 1914.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les provinces perdues restent un thème politique majeur pendant quarante ans.', 7),
    ('a060b4bd-1fcb-5a35-bd52-bc6a264a9535'::uuid, '72d36aba-f8ec-50c4-bc79-7fdddd2f6970'::uuid, 'Quel épisode diplomatique déclenche la guerre de 1870 ?', 'mcq', '["La dépêche d’Ems","Les entrevues de Plombières","Le congrès de Berlin","L’expédition des Mille"]'::jsonb, 0, 'Bismarck en publie une version qui rend la déclaration de guerre française inévitable.', 8),
    ('33a89257-5ff4-5648-a713-56327e214af7'::uuid, '5261a09c-a1d0-5d3e-bdd3-9ca9478eda5b'::uuid, 'Quand la Troisième République est-elle proclamée ?', 'mcq', '["Le 4 septembre 1870","Le 18 mars 1871","Le 30 janvier 1875","Le 16 mai 1877"]'::jsonb, 0, 'La proclamation suit immédiatement la capitulation de Sedan.', 1),
    ('495e7c3f-1f22-509a-8ded-831eb09a2ffb'::uuid, '5261a09c-a1d0-5d3e-bdd3-9ca9478eda5b'::uuid, 'Quelle est la majorité de l’Assemblée élue en février 1871 ?', 'mcq', '["Monarchiste","Républicaine","Bonapartiste","Socialiste"]'::jsonb, 0, 'Elle est élue sur la question de la paix, que les monarchistes portent alors.', 2),
    ('2267acc6-0d61-51b8-92a5-85217b947633'::uuid, '5261a09c-a1d0-5d3e-bdd3-9ca9478eda5b'::uuid, 'Pourquoi la restauration monarchique échoue-t-elle en 1873 ?', 'mcq', '["Le comte de Chambord refuse le drapeau tricolore","Le peuple vote contre par référendum","L’Allemagne s’y oppose","Les deux prétendants meurent"]'::jsonb, 0, 'Un symbole suffit à faire échouer un régime déjà divisé.', 3),
    ('b283fa75-64ef-5679-9178-40fa8618c77c'::uuid, '5261a09c-a1d0-5d3e-bdd3-9ca9478eda5b'::uuid, 'Qu’ajoute l’amendement Wallon en janvier 1875 ?', 'mcq', '["Le mot « République » dans les lois constitutionnelles","Le suffrage universel","La liberté de la presse","La séparation des Églises et de l’État"]'::jsonb, 0, 'Adopté à une voix de majorité : 353 contre 352.', 4),
    ('00e806d9-0b09-59c7-8063-eefcd4f6f8bd'::uuid, '5261a09c-a1d0-5d3e-bdd3-9ca9478eda5b'::uuid, 'Quelles institutions les lois de 1875 mettent-elles en place ?', 'mcq', '["Une Chambre des députés, un Sénat et un président élu par les Chambres","Une assemblée unique et un président élu au suffrage universel","Un consulat","Une monarchie parlementaire"]'::jsonb, 0, 'Le bicamérisme est le prix du ralliement des orléanistes.', 5),
    ('d6f77be2-b298-5e3b-9608-1b308ebf5bb9'::uuid, '5261a09c-a1d0-5d3e-bdd3-9ca9478eda5b'::uuid, 'Que se passe-t-il lors de la crise du 16 mai 1877 ?', 'mcq', '["Mac-Mahon dissout la Chambre et perd les élections","Le président est destitué","La République est abolie","Le Sénat est supprimé"]'::jsonb, 0, 'Après cet échec, la dissolution ne sera plus utilisée sous la Troisième République.', 6),
    ('3dca34cd-fb33-51cc-836b-f0bba8bdbfde'::uuid, '5261a09c-a1d0-5d3e-bdd3-9ca9478eda5b'::uuid, 'La crise de 1877 renforce le pouvoir du président de la République.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle l’affaiblit durablement au profit des Chambres.', 7),
    ('34397771-9fe6-555e-b94f-383888d7289e'::uuid, '5261a09c-a1d0-5d3e-bdd3-9ca9478eda5b'::uuid, 'Qui écrase la Commune de Paris en mai 1871 ?', 'mcq', '["Le gouvernement de Thiers","L’armée prussienne","La Garde nationale","Le gouvernement de Mac-Mahon"]'::jsonb, 0, 'La Semaine sanglante est menée par les troupes versaillaises.', 8),
    ('2e97dd58-baab-5363-9146-4ef706f47ceb'::uuid, 'b046e0de-5cae-54e1-af88-22931e899939'::uuid, 'Quelle liberté fondamentale la loi de 1881 consacre-t-elle ?', 'mcq', '["La liberté de la presse","La liberté syndicale","La liberté d’association","La liberté de culte"]'::jsonb, 0, 'Elle supprime l’autorisation préalable et limite fortement les délits de presse.', 1),
    ('325607ac-2a08-528c-91e4-f7eab408aad0'::uuid, 'b046e0de-5cae-54e1-af88-22931e899939'::uuid, 'Que fait la loi Waldeck-Rousseau de 1884 ?', 'mcq', '["Elle légalise les syndicats professionnels","Elle sépare les Églises et l’État","Elle crée l’école gratuite","Elle instaure l’impôt sur le revenu"]'::jsonb, 0, 'Vingt ans après la dépénalisation de la grève, le syndicat devient légal.', 2),
    ('487288d1-7705-58ce-9d4c-cf8f32b1dccf'::uuid, 'b046e0de-5cae-54e1-af88-22931e899939'::uuid, 'Que rendent les lois Ferry de 1881-1882 ?', 'mcq', '["L’école primaire gratuite, laïque et obligatoire","L’université gratuite","Le lycée obligatoire","La formation professionnelle obligatoire"]'::jsonb, 0, 'Obligation scolaire de 6 à 13 ans, pour les filles comme pour les garçons.', 3),
    ('9efedf72-3aab-52b7-b5e7-126300e9e66a'::uuid, 'b046e0de-5cae-54e1-af88-22931e899939'::uuid, 'La Marseillaise devient hymne national en 1879.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le 14 Juillet devient fête nationale l’année suivante, en 1880.', 4),
    ('344d775b-0e66-5303-ba0e-0f4777df2861'::uuid, 'b046e0de-5cae-54e1-af88-22931e899939'::uuid, 'Comment surnomme-t-on les instituteurs de la Troisième République ?', 'mcq', '["Les hussards noirs de la République","Les gardiens du temple","Les missionnaires laïques","Les sergents de la nation"]'::jsonb, 0, 'L’expression est de Charles Péguy.', 5),
    ('4c792e79-082e-5a96-8e1e-70c877a95e5e'::uuid, 'b046e0de-5cae-54e1-af88-22931e899939'::uuid, 'Quelle affaire divise profondément la France à partir de 1894 ?', 'mcq', '["L’affaire Dreyfus","L’affaire Stavisky","Le scandale de Panama seul","L’affaire Boulanger"]'::jsonb, 0, 'Elle oppose dreyfusards et antidreyfusards pendant plus de dix ans.', 6),
    ('e4407fec-f31e-5359-8786-01e4509f9938'::uuid, 'b046e0de-5cae-54e1-af88-22931e899939'::uuid, 'Qui publie « J’accuse… ! » en 1898 ?', 'mcq', '["Émile Zola","Victor Hugo","Jean Jaurès","Georges Clemenceau"]'::jsonb, 0, 'La lettre ouverte paraît dans L’Aurore et relance l’affaire.', 7),
    ('10013753-7f9a-5996-b37a-9e20b1f6f2c1'::uuid, 'b046e0de-5cae-54e1-af88-22931e899939'::uuid, 'Qu’est-ce que le boulangisme ?', 'mcq', '["Un mouvement autoritaire et nationaliste qui menace la République à la fin des années 1880","Un syndicat de boulangers","Un courant socialiste","Une politique agricole"]'::jsonb, 0, 'La popularité du général Boulanger fait craindre un coup d’État.', 8),
    ('fa2cb25a-1329-5f01-ae29-fc20875132f0'::uuid, 'aad11c54-b82d-5254-aa9f-5ba843f835d5'::uuid, 'Que dispose la loi du 9 décembre 1905 ?', 'mcq', '["La République ne reconnaît ni ne salarie aucun culte","Les cultes sont interdits","Le catholicisme redevient religion d’État","L’Église contrôle les écoles"]'::jsonb, 0, 'Elle garantit la liberté de conscience et le libre exercice des cultes.', 1),
    ('ca8b41dd-56e2-5742-a170-57a848823e27'::uuid, 'aad11c54-b82d-5254-aa9f-5ba843f835d5'::uuid, 'Quel texte la loi de 1905 remplace-t-elle ?', 'mcq', '["Le Concordat de 1801","La loi Falloux","La Constitution civile du clergé","Le décret Schoelcher"]'::jsonb, 0, 'Fin du régime concordataire signé par Bonaparte.', 2),
    ('e64f6f4d-dcbf-554d-8024-697ea06fcae8'::uuid, 'aad11c54-b82d-5254-aa9f-5ba843f835d5'::uuid, 'Que provoquent les inventaires de 1906 ?', 'mcq', '["Des incidents parfois violents lors du recensement des biens d’église","La fermeture de toutes les églises","Une grève générale","La démission du gouvernement"]'::jsonb, 0, 'La résistance est forte dans les régions les plus catholiques.', 3),
    ('5e659b55-27b4-504e-a529-cfc0c6073ffb'::uuid, 'aad11c54-b82d-5254-aa9f-5ba843f835d5'::uuid, 'Quelle loi sociale est votée en 1906 ?', 'mcq', '["Le repos hebdomadaire obligatoire","Les congés payés","La semaine de 40 heures","Le salaire minimum"]'::jsonb, 0, 'Un jour de repos par semaine devient une obligation légale.', 4),
    ('a32e659a-9738-5450-a3cd-118a4ea63ae6'::uuid, 'aad11c54-b82d-5254-aa9f-5ba843f835d5'::uuid, 'Quand la CGT est-elle fondée ?', 'mcq', '["En 1895","En 1884","En 1905","En 1919"]'::jsonb, 0, 'La Confédération générale du travail naît onze ans après la légalisation des syndicats.', 5),
    ('18dc4e1c-ecb2-5c9b-bdb9-db43c7b1b6ed'::uuid, 'aad11c54-b82d-5254-aa9f-5ba843f835d5'::uuid, 'Qui dirige la SFIO, parti socialiste unifié créé en 1905 ?', 'mcq', '["Jean Jaurès en est la grande figure","Georges Clemenceau","Jules Guesde seul","Aristide Briand seul"]'::jsonb, 0, 'Jaurès en devient le principal orateur et le directeur de L’Humanité.', 6),
    ('4b454cb3-267e-59a0-8fbb-d5c05e5e4284'::uuid, 'aad11c54-b82d-5254-aa9f-5ba843f835d5'::uuid, 'Que fait la loi de trois ans en 1913 ?', 'mcq', '["Elle allonge la durée du service militaire","Elle prolonge le mandat des députés","Elle allonge la scolarité obligatoire","Elle limite le travail des enfants"]'::jsonb, 0, 'Réponse à la montée des tensions avec l’Allemagne.', 7),
    ('d5bff12c-f62d-5551-bdb9-f79724bc3b96'::uuid, 'aad11c54-b82d-5254-aa9f-5ba843f835d5'::uuid, 'Jean Jaurès est assassiné le 31 juillet 1914.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le principal opposant à la guerre disparaît trois jours avant la mobilisation générale.', 8),
    ('3f83f3c3-721a-5201-855f-b30b068f890b'::uuid, 'b2c40f3b-b546-5272-ad7f-ff68fe0a3a5f'::uuid, 'Quelles énergies caractérisent la deuxième révolution industrielle ?', 'mcq', '["L’électricité et le pétrole","Le charbon et la vapeur seuls","Le gaz de ville uniquement","L’énergie hydraulique seule"]'::jsonb, 0, 'Elles s’ajoutent au charbon et transforment usines et transports.', 1),
    ('dbf3e332-b42c-5599-8c75-f52420bc73a5'::uuid, 'b2c40f3b-b546-5272-ad7f-ff68fe0a3a5f'::uuid, 'Quelle part des actifs français travaille encore dans l’agriculture vers 1911 ?', 'mcq', '["Environ 44 %","Environ 10 %","Environ 70 %","Environ 25 %"]'::jsonb, 0, 'La France reste beaucoup plus rurale que le Royaume-Uni ou l’Allemagne.', 2),
    ('a2de3d8f-b466-5726-83a3-c3cb248e80be'::uuid, 'b2c40f3b-b546-5272-ad7f-ff68fe0a3a5f'::uuid, 'Que protègent les tarifs Méline de 1892 ?', 'mcq', '["L’agriculture et l’industrie françaises par des droits de douane","Les colonies","Les banques","Les chemins de fer"]'::jsonb, 0, 'Ce protectionnisme freine l’exode rural et conserve la petite exploitation.', 3),
    ('9b334533-fe36-5e3d-857c-67832779c2a8'::uuid, 'b2c40f3b-b546-5272-ad7f-ff68fe0a3a5f'::uuid, 'Quelle particularité démographique distingue la France de ses voisins ?', 'mcq', '["Une croissance de la population très faible","Une explosion démographique","Une mortalité infantile record","Une émigration massive vers l’Amérique"]'::jsonb, 0, 'La natalité baisse tôt : la France recourt davantage à l’immigration.', 4),
    ('5c77f0ff-f792-5d48-9b14-0ce8471d1e0a'::uuid, 'b2c40f3b-b546-5272-ad7f-ff68fe0a3a5f'::uuid, 'D’où viennent principalement les immigrés en France avant 1914 ?', 'mcq', '["De Belgique, d’Italie et de Pologne","D’Afrique du Nord seulement","D’Asie","D’Amérique latine"]'::jsonb, 0, 'Ils travaillent surtout dans les mines, la sidérurgie et l’agriculture.', 5),
    ('697d35e4-70cd-5ac7-add8-9edd749a5708'::uuid, 'b2c40f3b-b546-5272-ad7f-ff68fe0a3a5f'::uuid, 'Renault est fondée en 1898.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’automobile est l’une des industries neuves de la période.', 6),
    ('5500dda7-a0ab-5b6c-a29f-f994eef27f68'::uuid, 'b2c40f3b-b546-5272-ad7f-ff68fe0a3a5f'::uuid, 'Qu’est-ce que le taylorisme ?', 'mcq', '["Une organisation scientifique du travail décomposant les tâches","Un syndicat","Une loi sociale","Une méthode agricole"]'::jsonb, 0, 'Il commence à s’introduire en France avant 1914, notamment chez Renault.', 7),
    ('7e8fb46c-7434-54ea-b005-09c3b46c6c96'::uuid, 'b2c40f3b-b546-5272-ad7f-ff68fe0a3a5f'::uuid, 'Quel groupe social nouveau se développe avec les bureaux et les grands magasins ?', 'mcq', '["Les employés","Les métayers","Les artisans ruraux","Les rentiers"]'::jsonb, 0, 'Ni ouvriers ni bourgeois, ils forment une classe moyenne salariée.', 8),
    ('36762b94-06bb-5eee-9f71-5f926f234163'::uuid, '2ff2a6b9-856d-5335-862e-557d41ad6f6c'::uuid, 'Que crée la loi Camille Sée en 1880 ?', 'mcq', '["L’enseignement secondaire public pour les filles","L’école primaire obligatoire","Les universités féminines","Le droit de vote des femmes"]'::jsonb, 0, 'Les lycées de jeunes filles ouvrent, sans programme identique à celui des garçons au départ.', 1),
    ('8a7592ec-8315-5377-b33e-7afad3d17615'::uuid, '2ff2a6b9-856d-5335-862e-557d41ad6f6c'::uuid, 'Quand les Françaises obtiennent-elles le droit de vote ?', 'mcq', '["En 1944","En 1918","En 1936","En 1905"]'::jsonb, 0, 'Bien après plusieurs voisins européens : le suffrage « universel » de la Troisième République est masculin.', 2),
    ('c8c09779-2db6-58af-b5c4-48f99c8c629e'::uuid, '2ff2a6b9-856d-5335-862e-557d41ad6f6c'::uuid, 'Quelle loi de 1898 protège les salariés ?', 'mcq', '["La loi sur les accidents du travail","La loi sur les retraites","La loi sur le repos hebdomadaire","La loi sur les congés payés"]'::jsonb, 0, 'Elle instaure une responsabilité de l’employeur sans faute à prouver.', 3),
    ('86eadcb3-0312-5e5a-8741-84ed13600ba7'::uuid, '2ff2a6b9-856d-5335-862e-557d41ad6f6c'::uuid, 'Qu’est-ce que la presse à un sou ?', 'mcq', '["Une presse populaire à très bas prix et à fort tirage","Une presse réservée aux élites","Un journal officiel","La presse syndicale"]'::jsonb, 0, 'Le Petit Journal dépasse le million d’exemplaires : l’information devient un bien de masse.', 4),
    ('6797f516-c281-5453-b169-6dc6bc91c26d'::uuid, '2ff2a6b9-856d-5335-862e-557d41ad6f6c'::uuid, 'Le Code civil de l’époque place la femme mariée sous l’autorité de son mari.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’incapacité juridique de la femme mariée ne disparaîtra qu’au XXe siècle.', 5),
    ('3dcd8b0e-9b4c-5dbe-bb49-5a10dc2a35b7'::uuid, '2ff2a6b9-856d-5335-862e-557d41ad6f6c'::uuid, 'Quelle innovation transforme la vie quotidienne des villes vers 1900 ?', 'mcq', '["L’éclairage électrique et le tramway","L’automobile pour tous","Le téléphone dans chaque foyer","La télévision"]'::jsonb, 0, 'La ville change plus vite que la campagne, ce qui creuse les écarts de mode de vie.', 6),
    ('3e1136cb-a622-50c5-b3b9-cfbc2c4e5f73'::uuid, '2ff2a6b9-856d-5335-862e-557d41ad6f6c'::uuid, 'Qui résiste le plus aux lois sociales avant 1914 ?', 'mcq', '["Une grande partie du patronat","Les syndicats","Les instituteurs","Les députés radicaux"]'::jsonb, 0, 'Les lois sont votées tard et souvent appliquées avec retard.', 7),
    ('1385392e-0721-5501-bd50-735cad45c136'::uuid, '2ff2a6b9-856d-5335-862e-557d41ad6f6c'::uuid, 'Quelle institution unifie les usages et la langue chez les jeunes hommes ?', 'mcq', '["Le service militaire","Le syndicat","La coopérative agricole","La mutuelle"]'::jsonb, 0, 'Avec l’école, il fait reculer les patois et diffuse une culture nationale.', 8),
    ('92856beb-e454-5971-bb6d-7934391cd1d5'::uuid, '70f2878d-0c99-5e82-8ae9-14147f64f4d7'::uuid, 'Quel rang occupe l’empire colonial français vers 1914 ?', 'mcq', '["Le deuxième après le Royaume-Uni","Le premier","Le troisième après l’Allemagne","Le cinquième"]'::jsonb, 0, 'Environ 10 millions de km² et 50 millions d’habitants.', 1),
    ('7ed31760-10df-51cd-9fcc-b363b6e1e210'::uuid, '70f2878d-0c99-5e82-8ae9-14147f64f4d7'::uuid, 'Que fait la conférence de Berlin de 1884-1885 ?', 'mcq', '["Elle fixe les règles du partage de l’Afrique entre Européens","Elle interdit la colonisation","Elle libère les colonies","Elle crée la SDN"]'::jsonb, 0, 'Elle impose notamment le principe de l’occupation effective.', 2),
    ('053237d2-0762-5e31-aa26-5634ca9ade06'::uuid, '70f2878d-0c99-5e82-8ae9-14147f64f4d7'::uuid, 'Quel incident oppose la France au Royaume-Uni en 1898 ?', 'mcq', '["Fachoda","Agadir","Tanger","Sedan"]'::jsonb, 0, 'La France recule au Soudan : la rivalité coloniale cède ensuite la place à l’Entente cordiale.', 3),
    ('bfd129df-8aa7-55a5-8dba-5140415d0958'::uuid, '70f2878d-0c99-5e82-8ae9-14147f64f4d7'::uuid, 'La Tunisie devient un protectorat français en 1881.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le Maroc suivra en 1912, après deux crises internationales.', 4),
    ('8af5c852-f1cf-52e2-a9f8-1e08f6873078'::uuid, '70f2878d-0c99-5e82-8ae9-14147f64f4d7'::uuid, 'Qui résiste à la conquête française en Afrique de l’Ouest ?', 'mcq', '["Samory Touré","Abd el-Krim","Chaka Zulu","Menelik II"]'::jsonb, 0, 'Sa résistance dure jusqu’en 1898.', 5),
    ('01f28831-49f0-58c9-9336-f34b8f713cd7'::uuid, '70f2878d-0c99-5e82-8ae9-14147f64f4d7'::uuid, 'Quelle innovation militaire facilite les conquêtes ?', 'mcq', '["Le fusil à répétition et la mitrailleuse","Le char d’assaut","L’avion","Le sous-marin"]'::jsonb, 0, 'L’écart technologique est décisif face aux armées locales.', 6),
    ('f45aabc0-06a3-55cd-b0e0-014ab383a3c1'::uuid, '70f2878d-0c99-5e82-8ae9-14147f64f4d7'::uuid, 'Quel type de colonie est l’Algérie ?', 'mcq', '["Une colonie de peuplement rattachée administrativement à la France","Un protectorat","Un territoire sous mandat","Un comptoir commercial"]'::jsonb, 0, 'Trois départements français y sont créés, avec une importante population européenne.', 7),
    ('46ff81ac-dfc9-525f-bc58-3ac09dd11275'::uuid, '70f2878d-0c99-5e82-8ae9-14147f64f4d7'::uuid, 'Les crises marocaines de 1905 et 1911 opposent la France à quel pays ?', 'mcq', '["L’Allemagne","L’Italie","L’Espagne","Le Royaume-Uni"]'::jsonb, 0, 'Elles renforcent les blocs qui s’affronteront en 1914.', 8),
    ('f1523850-3976-5b34-9218-79c765a5a579'::uuid, 'bbd88b21-01d4-5073-b98a-48f6e559269f'::uuid, 'Quel homme politique défend en 1885 le « devoir des races supérieures » ?', 'mcq', '["Jules Ferry","Georges Clemenceau","Jean Jaurès","Léon Gambetta"]'::jsonb, 0, 'Son discours devant la Chambre est le texte de référence sur la mission civilisatrice.', 1),
    ('42ea40e7-4d80-56df-b10a-a0cbad506c27'::uuid, 'bbd88b21-01d4-5073-b98a-48f6e559269f'::uuid, 'Qui s’oppose à Ferry lors de ce débat ?', 'mcq', '["Georges Clemenceau","Jules Guesde","Raymond Poincaré","Paul Doumer"]'::jsonb, 0, 'Il dénonce le coût humain et le détournement de la question alsacienne.', 2),
    ('b9d0c830-61f6-54e8-9430-7d429f313b1f'::uuid, 'bbd88b21-01d4-5073-b98a-48f6e559269f'::uuid, 'Quelles motivations économiques poussent à la colonisation ?', 'mcq', '["Des débouchés, des matières premières et des placements","La lutte contre la surpopulation","La recherche de main-d’œuvre pour la métropole","Le besoin de terres agricoles en France"]'::jsonb, 0, 'L’empire devient un marché protégé pour l’industrie française.', 3),
    ('957d6a3b-ddfe-5a7c-829a-4c55bcca4389'::uuid, 'bbd88b21-01d4-5073-b98a-48f6e559269f'::uuid, 'La « mission civilisatrice » repose sur une hiérarchie des races.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Cette idéologie, très répandue à l’époque, justifie la domination.', 4),
    ('350e4ba6-4295-5618-b4d0-ef4c8895a715'::uuid, 'bbd88b21-01d4-5073-b98a-48f6e559269f'::uuid, 'Comment l’empire est-il diffusé dans la culture métropolitaine ?', 'mcq', '["Expositions, manuels, cartes postales et publicités","Uniquement par la radio","Par le cinéma seul","Il reste inconnu du grand public"]'::jsonb, 0, 'L’imagerie coloniale imprègne le quotidien des Français.', 5),
    ('c0df6b44-bf81-51d8-b8ab-a98046689a87'::uuid, 'bbd88b21-01d4-5073-b98a-48f6e559269f'::uuid, 'Quel prélèvement pèse sur les populations colonisées ?', 'mcq', '["L’impôt de capitation","La TVA","L’impôt sur le revenu","La dîme"]'::jsonb, 0, 'Il s’ajoute au travail forcé et aux réquisitions.', 6),
    ('e2d8bc22-7aa4-50dd-89eb-e557be20e3ed'::uuid, 'bbd88b21-01d4-5073-b98a-48f6e559269f'::uuid, 'Quel argument stratégique justifie l’expansion après 1871 ?', 'mcq', '["Restaurer le prestige de la France après la défaite","Préparer l’invasion de l’Allemagne","Trouver de nouveaux alliés européens","Peupler les colonies de Français"]'::jsonb, 0, 'La grandeur retrouvée outre-mer compense la défaite continentale.', 7),
    ('4c7b5383-3df8-50aa-8106-21ab105382c8'::uuid, 'bbd88b21-01d4-5073-b98a-48f6e559269f'::uuid, 'Qui dénonce l’exploitation coloniale au nom du socialisme ?', 'mcq', '["Jean Jaurès","Jules Ferry","Paul Bert","Albert Sarraut"]'::jsonb, 0, 'Sa critique reste minoritaire avant 1914.', 8),
    ('fb2e1c39-dbd5-5960-9c7a-a059122120e1'::uuid, '52c9d324-0424-56c5-8e15-effcaa2518a5'::uuid, 'Quel statut ont la plupart des colonisés ?', 'mcq', '["Sujets français, sans droits politiques","Citoyens français","Étrangers protégés","Ressortissants autonomes"]'::jsonb, 0, 'Ils ne votent pas et relèvent d’un droit d’exception.', 1),
    ('0d4614b5-ab6b-5a3b-8e91-4469cbd9f30e'::uuid, '52c9d324-0424-56c5-8e15-effcaa2518a5'::uuid, 'Qu’est-ce que le Code de l’indigénat ?', 'mcq', '["Un régime d’exception permettant de punir les colonisés sans juge","Un code du travail colonial","Un recueil de coutumes locales","Un statut fiscal avantageux"]'::jsonb, 0, 'Créé en Algérie en 1881, il est étendu à d’autres colonies.', 2),
    ('6450259c-9382-527d-83ef-73ff6968d47f'::uuid, '52c9d324-0424-56c5-8e15-effcaa2518a5'::uuid, 'Quelle différence sépare une colonie d’un protectorat ?', 'mcq', '["Le protectorat conserve un souverain local sous contrôle français","La colonie est indépendante","Le protectorat élit des députés","La colonie n’a pas d’administration"]'::jsonb, 0, 'Tunisie et Maroc sont des protectorats, l’AOF est administrée directement.', 3),
    ('fcf469a6-e4c4-5183-911d-e3a8ecc0d2b7'::uuid, '52c9d324-0424-56c5-8e15-effcaa2518a5'::uuid, 'L’économie coloniale est d’abord orientée vers l’exportation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Cultures commerciales et mines alimentent la métropole, souvent au détriment des cultures vivrières.', 4),
    ('01d082dd-37ff-5a14-927b-26c9f99df615'::uuid, '52c9d324-0424-56c5-8e15-effcaa2518a5'::uuid, 'Qui sont les tirailleurs ?', 'mcq', '["Des soldats recrutés dans les colonies","Des colons armés","Des policiers métropolitains","Des chefs coutumiers"]'::jsonb, 0, 'Ils serviront massivement pendant la Première Guerre mondiale.', 5),
    ('89c8d9a7-d480-591d-af6c-30d394409ba7'::uuid, '52c9d324-0424-56c5-8e15-effcaa2518a5'::uuid, 'La scolarisation des enfants colonisés est-elle généralisée avant 1914 ?', 'mcq', '["Non, elle reste très minoritaire","Oui, elle est obligatoire partout","Oui, dès 1882","Elle est interdite"]'::jsonb, 0, 'L’école coloniale ne concerne qu’une petite minorité.', 6),
    ('1da3c561-95b4-5549-9a02-47c45cfa0211'::uuid, '52c9d324-0424-56c5-8e15-effcaa2518a5'::uuid, 'Quel effet inattendu produit l’école coloniale ?', 'mcq', '["Elle forme des élites qui réclameront l’égalité","Elle fait disparaître les langues locales","Elle empêche toute revendication","Elle supprime l’indigénat"]'::jsonb, 0, 'Les futurs leaders nationalistes en sont souvent issus.', 7),
    ('192b4ef4-f0f2-5eba-8ed4-4789327186dd'::uuid, '52c9d324-0424-56c5-8e15-effcaa2518a5'::uuid, 'Que subissent fréquemment les terres des colonisés ?', 'mcq', '["Des expropriations au profit des colons","Une redistribution égalitaire","Une mise en jachère obligatoire","Un rachat au prix du marché"]'::jsonb, 0, 'La question foncière est l’une des sources majeures de conflit.', 8),
    ('e2d78320-9ab6-548d-a40f-8de828f7029b'::uuid, '32cee14e-2ab7-529a-b725-27792a9da5b6'::uuid, 'Quel événement déclenche l’engrenage de juillet 1914 ?', 'mcq', '["L’assassinat de François-Ferdinand à Sarajevo","L’invasion de la Belgique","La bataille de la Marne","La crise d’Agadir"]'::jsonb, 0, 'L’ultimatum autrichien à la Serbie enclenche les alliances.', 1),
    ('7dc73d32-83ae-5134-985c-d3fa8b8f79d6'::uuid, '32cee14e-2ab7-529a-b725-27792a9da5b6'::uuid, 'Quelle bataille arrête l’avance allemande en septembre 1914 ?', 'mcq', '["La bataille de la Marne","La bataille de Verdun","La bataille de la Somme","La bataille du Chemin des Dames"]'::jsonb, 0, 'Elle met fin à la guerre de mouvement et ouvre la guerre de position.', 2),
    ('6bb6977c-ff14-52e6-a171-b097811c0b49'::uuid, '32cee14e-2ab7-529a-b725-27792a9da5b6'::uuid, 'Qu’appelle-t-on la course à la mer ?', 'mcq', '["Le débordement des armées vers le nord jusqu’à la mer du Nord","Une bataille navale","La course aux cuirassés d’avant-guerre","Le blocus des ports allemands"]'::jsonb, 0, 'Elle aboutit à un front continu de la mer du Nord à la Suisse.', 3),
    ('e96dcb5b-7461-5520-9651-3af86311fb30'::uuid, '32cee14e-2ab7-529a-b725-27792a9da5b6'::uuid, 'Quelles batailles marquent l’année 1916 ?', 'mcq', '["Verdun et la Somme","La Marne et Ypres","Tannenberg et Gallipoli","Jutland et Caporetto"]'::jsonb, 0, 'Des centaines de milliers de morts pour des gains territoriaux minimes.', 4),
    ('a76e1040-f8f0-59e1-bb59-c282f10566bd'::uuid, '32cee14e-2ab7-529a-b725-27792a9da5b6'::uuid, 'Que se passe-t-il en 1917 ?', 'mcq', '["Mutineries françaises, révolutions russes et entrée en guerre des États-Unis","L’armistice","La bataille de la Marne","L’invasion de la Belgique"]'::jsonb, 0, 'C’est l’année de tous les basculements.', 5),
    ('fb52df96-5528-5646-8848-3a208221be2a'::uuid, '32cee14e-2ab7-529a-b725-27792a9da5b6'::uuid, 'Le traité de Brest-Litovsk fait sortir la Russie de la guerre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Signé en mars 1918, il permet à l’Allemagne de reporter ses forces à l’Ouest.', 6),
    ('35534833-abef-5fbe-8cb6-ec326b112a95'::uuid, '32cee14e-2ab7-529a-b725-27792a9da5b6'::uuid, 'Quand l’armistice est-il signé ?', 'mcq', '["Le 11 novembre 1918","Le 28 juin 1919","Le 11 novembre 1919","Le 3 août 1914"]'::jsonb, 0, 'Il est signé à Rethondes, dans la forêt de Compiègne.', 7),
    ('b0423b37-8af8-57d9-9a5a-6a437a3f742b'::uuid, '32cee14e-2ab7-529a-b725-27792a9da5b6'::uuid, 'Pourquoi cette guerre est-elle mondiale ?', 'mcq', '["Par les empires coloniaux, les Dominions et l’entrée d’acteurs extra-européens","Parce qu’elle se déroule sur tous les continents à parts égales","Parce que tous les États du monde y participent","Parce qu’elle commence en Asie"]'::jsonb, 0, 'Les combats se concentrent en Europe, mais les ressources et les hommes viennent du monde entier.', 8),
    ('df66fb43-e51a-53d1-b3d1-169fd8212091'::uuid, '8d6b5ded-cb05-5b68-b770-04eceed6097f'::uuid, 'Qu’est-ce qu’une guerre totale ?', 'mcq', '["Une guerre qui mobilise l’économie, les esprits et les populations entières","Une guerre menée sur tous les continents","Une guerre sans prisonniers","Une guerre qui dure plus de quatre ans"]'::jsonb, 0, 'Le front et l’arrière sont également engagés.', 1),
    ('c87d8dd3-2d29-57fc-88a9-67925ee30f32'::uuid, '8d6b5ded-cb05-5b68-b770-04eceed6097f'::uuid, 'Comment appelle-t-on les femmes travaillant dans les usines d’armement ?', 'mcq', '["Les munitionnettes","Les poilues","Les auxiliaires","Les marraines de guerre"]'::jsonb, 0, 'Elles remplacent les hommes mobilisés, souvent à des salaires inférieurs.', 2),
    ('bf82c449-cd6f-5ef8-af38-37fe96e60741'::uuid, '8d6b5ded-cb05-5b68-b770-04eceed6097f'::uuid, 'Qu’est-ce que le « bourrage de crâne » ?', 'mcq', '["La propagande et la censure de l’information","Un entraînement militaire","Une méthode d’enseignement","Un traitement médical"]'::jsonb, 0, 'L’expression vient des soldats eux-mêmes, qui lisent la presse au front.', 3),
    ('c979b98d-95de-50b9-96dc-c5f1ed17a508'::uuid, '8d6b5ded-cb05-5b68-b770-04eceed6097f'::uuid, 'Quel génocide est perpétré pendant la guerre ?', 'mcq', '["Le génocide des Arméniens","Le génocide rwandais","La Shoah","Le génocide cambodgien"]'::jsonb, 0, 'Environ 1,2 million de morts entre 1915 et 1916, organisé par le pouvoir jeune-turc.', 4),
    ('39408610-0393-509a-aa53-1291d9bb7417'::uuid, '8d6b5ded-cb05-5b68-b770-04eceed6097f'::uuid, 'Combien de soldats français meurent pendant la guerre ?', 'mcq', '["Environ 1,4 million","Environ 300 000","Environ 5 millions","Environ 700 000"]'::jsonb, 0, 'Auxquels s’ajoutent 4 millions de blessés, dont de nombreux invalides.', 5),
    ('32ace588-8265-5deb-9805-80b8059a13cf'::uuid, '8d6b5ded-cb05-5b68-b770-04eceed6097f'::uuid, 'Les monuments aux morts sont présents dans presque toutes les communes françaises.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils traduisent l’ampleur d’un deuil qui touche chaque village.', 6),
    ('0a3cb493-aa37-532b-973a-f38eac713528'::uuid, '8d6b5ded-cb05-5b68-b770-04eceed6097f'::uuid, 'Comment les États financent-ils la guerre ?', 'mcq', '["Par l’emprunt et l’inflation","Par l’impôt seul","Par les colonies uniquement","Par les dons privés"]'::jsonb, 0, 'Les emprunts nationaux et la création monétaire pèseront sur l’après-guerre.', 7),
    ('10396a45-2725-5444-951e-a5f2b987e78e'::uuid, '8d6b5ded-cb05-5b68-b770-04eceed6097f'::uuid, 'Quel rôle jouent les colonies dans le conflit ?', 'mcq', '["Elles fournissent des soldats et des travailleurs","Elles restent à l’écart","Elles se révoltent toutes","Elles financent seules la guerre"]'::jsonb, 0, 'Tirailleurs et travailleurs coloniaux sont massivement mobilisés.', 8),
    ('09127cb6-ba42-55bd-9522-992e8e109134'::uuid, '8677b4da-402b-53f9-8ac0-8ab2089ed6ea'::uuid, 'Quand le traité de Versailles est-il signé ?', 'mcq', '["Le 28 juin 1919","Le 11 novembre 1918","Le 10 janvier 1920","Le 18 janvier 1919"]'::jsonb, 0, 'Cinq ans jour pour jour après l’attentat de Sarajevo.', 1),
    ('89899143-3663-5d0d-9a7f-7789f40ffff0'::uuid, '8677b4da-402b-53f9-8ac0-8ab2089ed6ea'::uuid, 'Que prévoit l’article 231 du traité ?', 'mcq', '["La responsabilité de l’Allemagne dans la guerre","La création de la SDN","Le désarmement général","Le droit des peuples"]'::jsonb, 0, 'Il fonde juridiquement les réparations imposées à l’Allemagne.', 2),
    ('e7fa84ba-9e1f-5d57-84f0-8ac54155ad33'::uuid, '8677b4da-402b-53f9-8ac0-8ab2089ed6ea'::uuid, 'Combien d’empires disparaissent à l’issue de la guerre ?', 'mcq', '["Quatre : allemand, austro-hongrois, russe et ottoman","Deux","Trois","Cinq"]'::jsonb, 0, 'Leur effondrement redessine l’Europe centrale et le Proche-Orient.', 3),
    ('87ef7afd-3829-5c9e-ac55-6cf7017bb8dd'::uuid, '8677b4da-402b-53f9-8ac0-8ab2089ed6ea'::uuid, 'Qui énonce le principe du droit des peuples à disposer d’eux-mêmes ?', 'mcq', '["Le président Wilson","Clemenceau","Lloyd George","Lénine seul"]'::jsonb, 0, 'C’est l’un de ses 14 points, énoncés en janvier 1918.', 4),
    ('e5bd571b-80cf-53a5-9fcd-f637f4b415c0'::uuid, '8677b4da-402b-53f9-8ac0-8ab2089ed6ea'::uuid, 'Quelle organisation est créée en 1920 pour garantir la paix ?', 'mcq', '["La Société des Nations","L’ONU","L’OTAN","La Croix-Rouge"]'::jsonb, 0, 'Elle repose sur la sécurité collective et l’arbitrage.', 5),
    ('2a2a4883-386a-53af-87da-55e7ba8e81d8'::uuid, '8677b4da-402b-53f9-8ac0-8ab2089ed6ea'::uuid, 'Les États-Unis adhèrent à la Société des Nations.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le Sénat américain refuse de ratifier : l’organisation est privée de son principal promoteur.', 6),
    ('a21b33f5-24ae-5a94-89df-d57e544f203b'::uuid, '8677b4da-402b-53f9-8ac0-8ab2089ed6ea'::uuid, 'Quels États naissent en Europe centrale après 1918 ?', 'mcq', '["La Pologne, la Tchécoslovaquie et la Yougoslavie","L’Allemagne et l’Italie","La Belgique et les Pays-Bas","La Grèce et la Bulgarie"]'::jsonb, 0, 'Ils héritent de frontières contestées et de minorités importantes.', 7),
    ('60c09ede-5572-5c11-bae3-ac2e06a56e93'::uuid, '8677b4da-402b-53f9-8ac0-8ab2089ed6ea'::uuid, 'Pourquoi parle-t-on d’une paix fragile ?', 'mcq', '["Parce qu’elle humilie les vaincus et laisse des minorités mécontentes","Parce qu’elle n’a été signée par personne","Parce qu’elle supprime les frontières","Parce qu’elle désarme tous les pays"]'::jsonb, 0, 'Ces frustrations nourriront les révisions violentes des années 1930.', 8),
    ('aa8476db-a783-595b-89f4-df312654553d'::uuid, '3652c6b0-8fcd-59e7-9b83-6a29ddc3ce75'::uuid, 'Depuis quelle année la majorité de l’humanité vit-elle en ville ?', 'mcq', '["2007","1950","1990","2020"]'::jsonb, 0, 'Le seuil des 50 % de citadins est franchi au milieu des années 2000.', 1),
    ('44ae07c7-1e1d-54a4-9a66-7d7c99721082'::uuid, '3652c6b0-8fcd-59e7-9b83-6a29ddc3ce75'::uuid, 'Que mesure le taux d’urbanisation ?', 'mcq', '["La part de la population vivant en ville","La croissance annuelle des villes","La densité des villes","La surface bâtie"]'::jsonb, 0, 'Il est d’environ 56 % dans le monde aujourd’hui.', 2),
    ('6e59339a-6777-5155-8d6e-f9603b34ae4b'::uuid, '3652c6b0-8fcd-59e7-9b83-6a29ddc3ce75'::uuid, 'Qu’est-ce qu’une mégapole ?', 'mcq', '["Une agglomération de plus de 10 millions d’habitants","Une ville mondiale de commandement","Un chapelet de villes reliées","Une capitale politique"]'::jsonb, 0, 'À ne pas confondre avec la mégalopole, qui est un ensemble de villes.', 3),
    ('4e488e21-59f7-5572-b288-57692fdf40a4'::uuid, '3652c6b0-8fcd-59e7-9b83-6a29ddc3ce75'::uuid, 'Qu’est-ce qu’une mégalopole ?', 'mcq', '["Un vaste ensemble urbain formé de plusieurs grandes villes reliées","Une ville de plus de 20 millions d’habitants","Un quartier d’affaires","Une banlieue étendue"]'::jsonb, 0, 'Exemples : la Megalopolis américaine, la mégalopole japonaise.', 4),
    ('2fec4fdf-7381-573f-a104-f1fc89eabc31'::uuid, '3652c6b0-8fcd-59e7-9b83-6a29ddc3ce75'::uuid, 'Où se concentre aujourd’hui l’essentiel de la croissance urbaine ?', 'mcq', '["Dans les pays du Sud","En Europe occidentale","En Amérique du Nord","Au Japon"]'::jsonb, 0, 'Afrique et Asie fournissent la quasi-totalité des nouveaux citadins.', 5),
    ('43a703bd-7860-522a-a2da-f083956c7039'::uuid, '3652c6b0-8fcd-59e7-9b83-6a29ddc3ce75'::uuid, 'Le taux d’urbanisation des pays du Nord est faible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est très élevé (souvent plus de 80 %), mais il progresse peu.', 6),
    ('1b5bf9e2-86fa-5f0f-8ee0-0bd2a8c98915'::uuid, '3652c6b0-8fcd-59e7-9b83-6a29ddc3ce75'::uuid, 'Quels sont les deux moteurs de la croissance urbaine ?', 'mcq', '["L’exode rural et l’accroissement naturel","L’immigration internationale et le tourisme","L’industrialisation et l’agriculture","La périurbanisation et le télétravail"]'::jsonb, 0, 'Dans les pays du Sud, les deux se cumulent.', 7),
    ('a36b784e-a8b9-5966-97fa-593cac87b104'::uuid, '3652c6b0-8fcd-59e7-9b83-6a29ddc3ce75'::uuid, 'Qu’appelle-t-on étalement urbain ?', 'mcq', '["L’extension spatiale de la ville sur ses marges","La densification du centre","La construction de tours","La rénovation des quartiers anciens"]'::jsonb, 0, 'Il consomme des espaces agricoles et allonge les déplacements.', 8),
    ('6270ab32-7c05-56a5-b704-a122b0eefdef'::uuid, '73414596-caab-52b2-a24f-5afc0aaf1efc'::uuid, 'Qu’est-ce que la métropolisation ?', 'mcq', '["La concentration des hommes, des activités et du commandement dans les grandes villes","La croissance des villes moyennes","L’étalement des banlieues","Le retour à la campagne"]'::jsonb, 0, 'Elle se mesure surtout aux fonctions, pas seulement à la population.', 1),
    ('474414a4-97c2-523e-8d10-99532c8e1c81'::uuid, '73414596-caab-52b2-a24f-5afc0aaf1efc'::uuid, 'Qu’est-ce qui définit une métropole ?', 'mcq', '["Ses fonctions de commandement","Sa seule population","Sa superficie","Son ancienneté"]'::jsonb, 0, 'Sièges sociaux, bourses, universités, médias, hubs de transport.', 2),
    ('17587224-f9a4-5285-a61b-6043541e815b'::uuid, '73414596-caab-52b2-a24f-5afc0aaf1efc'::uuid, 'Une mégapole est forcément une métropole.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Lagos ou Dacca sont des mégapoles sans être des métropoles de rang mondial.', 3),
    ('ac71d092-062d-5813-840e-094be204bb0c'::uuid, '73414596-caab-52b2-a24f-5afc0aaf1efc'::uuid, 'Qu’appelle-t-on l’archipel métropolitain mondial ?', 'mcq', '["Le réseau des grandes métropoles plus reliées entre elles qu’à leur arrière-pays","Un ensemble d’îles urbanisées","Les métropoles portuaires","Les capitales politiques"]'::jsonb, 0, 'L’image insiste sur la mise en réseau par-dessus les territoires.', 4),
    ('04252df3-6fe1-596f-9359-1d22254257bb'::uuid, '73414596-caab-52b2-a24f-5afc0aaf1efc'::uuid, 'Quelles villes sont considérées comme des villes globales ?', 'mcq', '["New York, Londres, Tokyo","Lagos, Dacca, Kinshasa","Lyon, Manchester, Osaka","Le Caire, Karachi, Lima"]'::jsonb, 0, 'Elles concentrent les fonctions financières et décisionnelles de rang mondial.', 5),
    ('c3c20854-8156-5fe0-b36b-5e8cb4244662'::uuid, '73414596-caab-52b2-a24f-5afc0aaf1efc'::uuid, 'Qu’est-ce que le marketing territorial ?', 'mcq', '["La promotion d’une ville pour attirer investisseurs, touristes et habitants qualifiés","La vente de terrains publics","La publicité commerciale en ville","Le classement des villes par l’ONU"]'::jsonb, 0, 'Il accompagne la compétition entre métropoles.', 6),
    ('b9979bf1-4306-5958-8f78-971b4bd7f7e3'::uuid, '73414596-caab-52b2-a24f-5afc0aaf1efc'::uuid, 'Quel effet la métropolisation produit-elle sur les autres territoires ?', 'mcq', '["Elle accentue les fractures avec les villes moyennes et les périphéries","Elle les enrichit également","Elle n’a aucun effet","Elle vide les métropoles"]'::jsonb, 0, 'C’est l’un des grands débats de l’aménagement contemporain.', 7),
    ('23bb3b89-474a-5071-accf-0e18828a44eb'::uuid, '73414596-caab-52b2-a24f-5afc0aaf1efc'::uuid, 'Quels acteurs pilotent la métropolisation ?', 'mcq', '["Firmes transnationales, États et collectivités","Uniquement l’ONU","Uniquement les habitants","Uniquement les investisseurs étrangers"]'::jsonb, 0, 'Les stratégies se croisent et parfois s’opposent.', 8),
    ('0581f1ba-1083-5a55-b1b9-1ca2c5bdd16b'::uuid, 'e6f96576-37a7-5b53-80da-77ce512b0613'::uuid, 'Quels critères servent à hiérarchiser les métropoles ?', 'mcq', '["Poids économique, rayonnement culturel, connectivité, influence politique","La superficie et le climat","Le nombre de monuments","La densité seule"]'::jsonb, 0, 'Les classements croisent plusieurs indicateurs de fonctions.', 1),
    ('0ff29cea-886a-5325-9be6-d3eb3175b61b'::uuid, 'e6f96576-37a7-5b53-80da-77ce512b0613'::uuid, 'Quelles métropoles montent le plus vite dans la hiérarchie mondiale ?', 'mcq', '["Celles des pays émergents comme Shanghai ou Dubaï","Celles d’Europe de l’Ouest","Celles d’Amérique du Nord","Celles d’Afrique subsaharienne"]'::jsonb, 0, 'La croissance asiatique redessine le classement mondial.', 2),
    ('96295e3b-9a91-5701-a0aa-07b8a5760026'::uuid, 'e6f96576-37a7-5b53-80da-77ce512b0613'::uuid, 'Qu’est-ce que la gentrification ?', 'mcq', '["L’arrivée de populations aisées dans un quartier populaire réhabilité","La construction de logements sociaux","Le départ des habitants vers la périphérie","La rénovation des zones industrielles"]'::jsonb, 0, 'Elle entraîne souvent l’éviction des habitants les plus modestes.', 3),
    ('4018c968-16be-5007-8ce8-82830da76717'::uuid, 'e6f96576-37a7-5b53-80da-77ce512b0613'::uuid, 'Qu’est-ce qu’une gated community ?', 'mcq', '["Un quartier résidentiel fermé et sécurisé","Un bidonville","Un quartier d’affaires","Une zone industrielle"]'::jsonb, 0, 'Elle traduit une fragmentation sociale de l’espace urbain.', 4),
    ('ed25882a-1088-535e-8d28-51d609b517bb'::uuid, 'e6f96576-37a7-5b53-80da-77ce512b0613'::uuid, 'Dharavi, à Bombay, est un exemple de bidonville proche d’un quartier d’affaires.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les contrastes extrêmes se lisent parfois à l’échelle du quartier.', 5),
    ('670b8db2-b0dd-51a8-8d3c-8814c1ff4175'::uuid, 'e6f96576-37a7-5b53-80da-77ce512b0613'::uuid, 'Une métropole très peuplée est-elle forcément influente ?', 'mcq', '["Non, la population ne fait pas les fonctions de commandement","Oui, toujours","Oui, si elle est capitale","Oui, dans les pays du Sud"]'::jsonb, 0, 'Beaucoup de mégapoles du Sud restent peu connectées aux flux mondiaux.', 6),
    ('e2b84358-9838-5f9e-bcc9-32ea8ae107db'::uuid, 'e6f96576-37a7-5b53-80da-77ce512b0613'::uuid, 'Qu’est-ce que la ségrégation socio-spatiale ?', 'mcq', '["La séparation des groupes sociaux dans l’espace urbain","Le classement des villes","La spécialisation économique des quartiers","La densification du centre"]'::jsonb, 0, 'Elle se lit dans les prix du foncier autant que dans les politiques de logement.', 7),
    ('64826310-8775-595e-8fa5-1cc5c239c2bc'::uuid, 'e6f96576-37a7-5b53-80da-77ce512b0613'::uuid, 'Que mesure la connectivité d’une métropole ?', 'mcq', '["Son insertion dans les réseaux de transport et de communication","Le nombre de ses habitants","Sa surface bâtie","Son ancienneté"]'::jsonb, 0, 'Hubs aéroportuaires, ports, câbles sous-marins et flux financiers.', 8),
    ('c384eb43-4afc-5fa4-a1b8-1da4ea0378ef'::uuid, '7f7fa10b-28fa-5a33-8a90-406e60a7bd36'::uuid, 'Qu’est-ce qu’un CBD ?', 'mcq', '["Le quartier central des affaires","Un quartier résidentiel fermé","Une zone industrielle","Un centre commercial périphérique"]'::jsonb, 0, 'La Défense, Canary Wharf ou Pudong en sont des exemples.', 1),
    ('3e9148bf-a08c-5aa0-a612-53677a454c26'::uuid, '7f7fa10b-28fa-5a33-8a90-406e60a7bd36'::uuid, 'Qu’est-ce que la périurbanisation ?', 'mcq', '["L’extension de l’urbanisation au-delà des banlieues, sur des espaces ruraux","La densification du centre","La rénovation des friches","Le retour des habitants en ville"]'::jsonb, 0, 'Elle allonge les migrations pendulaires.', 2),
    ('c89540a1-6422-5586-84e3-416c97d0a734'::uuid, '7f7fa10b-28fa-5a33-8a90-406e60a7bd36'::uuid, 'Que deviennent souvent les friches industrielles et portuaires des métropoles ?', 'mcq', '["Des quartiers culturels, résidentiels ou d’affaires réhabilités","Des espaces agricoles","Des zones abandonnées définitivement","Des ports de commerce agrandis"]'::jsonb, 0, 'Les docks de Londres ou l’île de Nantes en sont des exemples.', 3),
    ('3a2fc752-377e-530a-9ee0-3d89fb2b420e'::uuid, '7f7fa10b-28fa-5a33-8a90-406e60a7bd36'::uuid, 'Qu’est-ce qu’une edge city ?', 'mcq', '["Un pôle d’activités développé en périphérie métropolitaine","Le centre historique","Un bidonville","Une ville nouvelle du Sud"]'::jsonb, 0, 'Le terme vient des États-Unis : la métropole devient polycentrique.', 4),
    ('7ef2c2aa-6526-523a-aa39-48072af8d470'::uuid, '7f7fa10b-28fa-5a33-8a90-406e60a7bd36'::uuid, 'Les métropoles françaises ont reçu un statut institutionnel à partir de 2014.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La loi MAPTAM crée les métropoles pour coordonner l’action des communes.', 5),
    ('9664f0a2-11a1-5957-b453-a99b8152f547'::uuid, '7f7fa10b-28fa-5a33-8a90-406e60a7bd36'::uuid, 'Qu’est-ce qu’un déplacement pendulaire ?', 'mcq', '["Un trajet quotidien domicile-travail","Un déménagement saisonnier","Un trajet touristique","Une migration internationale"]'::jsonb, 0, 'Il structure les transports de l’aire métropolitaine.', 6),
    ('c7c900cf-75ab-53ee-9f9d-81575fde3e81'::uuid, '7f7fa10b-28fa-5a33-8a90-406e60a7bd36'::uuid, 'Que cherchent les projets de ville durable ?', 'mcq', '["Limiter l’étalement et l’empreinte environnementale","Accélérer la périurbanisation","Supprimer les transports en commun","Construire uniquement des tours"]'::jsonb, 0, 'Densification, transports collectifs, végétalisation, écoquartiers.', 7),
    ('a91b2c64-bf43-5f58-a748-a4e6e9d70f9e'::uuid, '7f7fa10b-28fa-5a33-8a90-406e60a7bd36'::uuid, 'Pourquoi la gouvernance métropolitaine est-elle difficile ?', 'mcq', '["Parce qu’une métropole rassemble de très nombreuses communes","Parce qu’elle dépend de l’ONU","Parce qu’elle n’a pas de budget","Parce que les habitants ne votent pas"]'::jsonb, 0, 'Transports, logement et urbanisme dépassent les limites communales.', 8),
    ('b4a791ba-eb02-57a3-b77e-49aee52aebea'::uuid, '2fd610b2-75f7-5e0b-8540-f4b412bcb5c0'::uuid, 'Combien d’habitants compte environ l’aire urbaine de Paris ?', 'mcq', '["Environ 13 millions","Environ 5 millions","Environ 20 millions","Environ 8 millions"]'::jsonb, 0, 'Elle produit près du tiers du PIB français.', 1),
    ('6c052e82-8b20-5803-9977-8004b65cf5d8'::uuid, '2fd610b2-75f7-5e0b-8540-f4b412bcb5c0'::uuid, 'Que désigne la macrocéphalie du territoire français ?', 'mcq', '["Le poids démesuré de Paris par rapport aux autres villes","La forte densité du littoral","Le vieillissement de la population","La concentration industrielle du Nord"]'::jsonb, 0, 'Aucune autre métropole française n’approche le poids parisien.', 2),
    ('52c7db65-be36-5bb7-9577-baa0a8a5e14a'::uuid, '2fd610b2-75f7-5e0b-8540-f4b412bcb5c0'::uuid, 'Quelle métropole française est spécialisée dans l’aéronautique ?', 'mcq', '["Toulouse","Lille","Rennes","Strasbourg"]'::jsonb, 0, 'Airbus y structure tout un système productif régional.', 3),
    ('6546b6ac-3c96-5a6d-aa69-2961376ea600'::uuid, '2fd610b2-75f7-5e0b-8540-f4b412bcb5c0'::uuid, 'Quels espaces français sont les plus fragilisés par la métropolisation ?', 'mcq', '["Les villes moyennes et les espaces ruraux isolés","Les métropoles régionales","Les littoraux touristiques","Les zones frontalières"]'::jsonb, 0, 'Commerces fermés, vieillissement, faible création d’emplois.', 4),
    ('c1588fd5-3368-52ea-8996-e81d182f9452'::uuid, '2fd610b2-75f7-5e0b-8540-f4b412bcb5c0'::uuid, 'Qu’est-ce que le programme Action cœur de ville ?', 'mcq', '["Un programme de revitalisation des centres de villes moyennes","Un plan de construction de métropoles","Une politique agricole","Un plan de transport ferroviaire"]'::jsonb, 0, 'Il vise commerces, logement et services dans les villes moyennes.', 5),
    ('4de955a6-bb92-5b91-a9f9-e1197cb1e0d6'::uuid, '2fd610b2-75f7-5e0b-8540-f4b412bcb5c0'::uuid, 'La France compte plusieurs métropoles de rang mondial.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seule Paris atteint ce rang ; les autres sont des métropoles régionales.', 6),
    ('01cd9571-13be-5910-8983-ae1a0394d91b'::uuid, '2fd610b2-75f7-5e0b-8540-f4b412bcb5c0'::uuid, 'Qu’est-ce qu’un pôle de compétitivité ?', 'mcq', '["Un regroupement d’entreprises, de laboratoires et de formations sur un même territoire","Une zone franche fiscale","Un port industriel","Un parc de loisirs"]'::jsonb, 0, 'Il vise à créer des synergies d’innovation.', 7),
    ('a5363302-03d5-55f9-9aaf-3ff4c42d27b1'::uuid, '2fd610b2-75f7-5e0b-8540-f4b412bcb5c0'::uuid, 'Quelle infrastructure renforce l’attractivité des métropoles régionales ?', 'mcq', '["La ligne à grande vitesse","Le canal à grand gabarit","L’autoroute urbaine","Le téléphérique"]'::jsonb, 0, 'La LGV rapproche Bordeaux, Rennes ou Lyon de Paris — et accentue parfois leur dépendance.', 8),
    ('21f1f7aa-b727-538d-8177-55703d8a461a'::uuid, '845ff95d-cb05-5ebb-9346-d67621e86ab2'::uuid, 'Quelle loi de 2014 crée le statut de métropole en France ?', 'mcq', '["La loi MAPTAM","La loi NOTRe seule","La loi SRU","La loi Chevènement"]'::jsonb, 0, 'La loi NOTRe (2015) complète ensuite la répartition des compétences.', 1),
    ('1d0961f7-9959-5c86-9ec7-b29c7c9a6f24'::uuid, '845ff95d-cb05-5ebb-9346-d67621e86ab2'::uuid, 'Combien de métropoles compte aujourd’hui la France ?', 'mcq', '["21","5","12","40"]'::jsonb, 0, 'Trois d’entre elles (Paris, Lyon, Marseille) ont un statut particulier.', 2),
    ('fe5fb623-002b-5a5c-b54a-cd355bdc3d2c'::uuid, '845ff95d-cb05-5ebb-9346-d67621e86ab2'::uuid, 'Quel quartier d’affaires se situe à Lyon ?', 'mcq', '["La Part-Dieu","La Défense","Euralille","Confluence uniquement"]'::jsonb, 0, 'C’est le deuxième quartier d’affaires français par sa surface de bureaux.', 3),
    ('506cffc4-f537-5803-abde-45e0246bc108'::uuid, '845ff95d-cb05-5ebb-9346-d67621e86ab2'::uuid, 'Qu’est-ce que l’ANRU ?', 'mcq', '["L’agence chargée de la rénovation urbaine des quartiers prioritaires","Une agence de transport","Un office du logement étudiant","Un opérateur foncier agricole"]'::jsonb, 0, 'Elle finance démolitions, reconstructions et requalifications.', 4),
    ('8934c91a-79e6-5364-ad9e-bc466d3f7e42'::uuid, '845ff95d-cb05-5ebb-9346-d67621e86ab2'::uuid, 'Le tramway a disparu des villes françaises depuis les années 1960.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est revenu depuis les années 1980 dans une vingtaine d’agglomérations.', 5),
    ('ddb290e8-35b2-5202-b31f-7b71a9accb04'::uuid, '845ff95d-cb05-5ebb-9346-d67621e86ab2'::uuid, 'Quelles inégalités marquent les métropoles françaises ?', 'mcq', '["De fortes différences de revenus et de réussite scolaire entre communes voisines","Des écarts uniquement entre régions","Aucune inégalité notable","Des écarts limités au logement"]'::jsonb, 0, 'Les contrastes internes sont parfois plus forts que les contrastes régionaux.', 6),
