    ('dd6bba43-bcbd-5a76-a24d-4b218d085645'::uuid, 'a1be1ac9-8655-5b6e-8196-97c81394c95d'::uuid, 'Qu’appelle-t-on la diagonale des faibles densités ?', 'mcq', '["Une bande allant du Nord-Est au Sud-Ouest où les densités sont très basses","Le littoral atlantique","La vallée du Rhône","Le Bassin parisien"]'::jsonb, 0, 'Elle traverse la France de la Meuse aux Landes.', 3),
    ('e238de90-3702-517c-abad-3cf9446225f7'::uuid, 'a1be1ac9-8655-5b6e-8196-97c81394c95d'::uuid, 'Les espaces ruraux français continuent de se vider globalement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Depuis les années 1970, beaucoup de communes rurales regagnent des habitants.', 4),
    ('1e62bd8d-1d60-508f-8c4b-f30bb233ac0d'::uuid, 'a1be1ac9-8655-5b6e-8196-97c81394c95d'::uuid, 'Quel phénomène récent renforce l’attractivité rurale ?', 'mcq', '["Le développement du télétravail","La baisse des prix agricoles","La fermeture des écoles","La hausse du prix des carburants"]'::jsonb, 0, 'Il s’est accéléré à partir de 2020.', 5),
    ('fc2c66a8-90f7-5ce7-b8a5-883f7e02241a'::uuid, 'a1be1ac9-8655-5b6e-8196-97c81394c95d'::uuid, 'Qu’est-ce que la multifonctionnalité des espaces ruraux ?', 'mcq', '["Le fait qu’ils remplissent plusieurs fonctions : productive, résidentielle, récréative, écologique","Le fait qu’ils accueillent plusieurs cultures","La diversité des paysages","La présence de plusieurs communes"]'::jsonb, 0, 'C’est la notion centrale du chapitre.', 6),
    ('de9567bf-36e2-5f33-b59a-5a6530a45d5f'::uuid, 'a1be1ac9-8655-5b6e-8196-97c81394c95d'::uuid, 'Quel est le principal handicap des campagnes isolées ?', 'mcq', '["L’éloignement des services et la dépendance à la voiture","L’excès de population","La pollution industrielle","Le prix élevé du foncier"]'::jsonb, 0, 'Santé, école et commerces s’éloignent avec la baisse de population.', 7),
    ('2a43b762-02c3-50a7-9daf-ff34c110e4bd'::uuid, 'a1be1ac9-8655-5b6e-8196-97c81394c95d'::uuid, 'Qu’est-ce que le continuum urbain-rural ?', 'mcq', '["L’idée d’un dégradé entre ville et campagne plutôt qu’une frontière nette","La fusion administrative des communes","Un corridor écologique","Une ligne de transport"]'::jsonb, 0, 'Le périurbain rend la limite ville-campagne floue.', 8),
    ('3e11f5e1-88cd-5288-98aa-c4ee47682c98'::uuid, '5f691160-9e94-52a5-9b3b-5695515b736e'::uuid, 'Quelle part du territoire français la surface agricole utile couvre-t-elle environ ?', 'mcq', '["La moitié","Un quart","Les trois quarts","Un dixième"]'::jsonb, 0, 'Alors que les agriculteurs représentent moins de 2 % des actifs.', 1),
    ('fe27aa56-f30f-5f9e-b2b6-c2733754d177'::uuid, '5f691160-9e94-52a5-9b3b-5695515b736e'::uuid, 'Qu’est-ce que l’agriculture vivrière ?', 'mcq', '["Une agriculture destinée d’abord à nourrir la famille du producteur","Une agriculture exportatrice","Une agriculture biologique","Une agriculture urbaine"]'::jsonb, 0, 'Elle reste dominante dans une partie du Sud.', 2),
    ('a35ead61-3fd2-562b-8044-1d357e5ddeff'::uuid, '5f691160-9e94-52a5-9b3b-5695515b736e'::uuid, 'Qu’est-ce que l’agriculture de firme ?', 'mcq', '["Une agriculture pilotée par des investisseurs sur de très grandes surfaces","Une exploitation familiale","Une coopérative agricole","Une ferme pédagogique"]'::jsonb, 0, 'Elle se développe notamment en Amérique du Sud et en Europe de l’Est.', 3),
    ('c78b8cbd-b9cf-5a0b-af98-917acc4b6c3a'::uuid, '5f691160-9e94-52a5-9b3b-5695515b736e'::uuid, 'Qu’est-ce que le land grabbing ?', 'mcq', '["L’acquisition massive de terres agricoles à l’étranger par des États ou des firmes","La lutte contre l’érosion","Le remembrement des parcelles","La vente de terres aux jeunes agriculteurs"]'::jsonb, 0, 'Il concerne surtout l’Afrique subsaharienne et l’Amérique latine.', 4),
    ('a7b2e2da-b88e-5d3f-9641-3f914d7d04bb'::uuid, '5f691160-9e94-52a5-9b3b-5695515b736e'::uuid, 'Le nombre d’exploitations agricoles françaises augmente.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il diminue fortement depuis des décennies, tandis que la taille moyenne augmente.', 5),
    ('f9dcc675-0880-5cf8-9a86-13bd5e0dcc0c'::uuid, '5f691160-9e94-52a5-9b3b-5695515b736e'::uuid, 'Que reproche-t-on au modèle productiviste ?', 'mcq', '["Ses effets sur les sols, l’eau et la biodiversité","Ses faibles rendements","Son coût pour les consommateurs","Son manque de mécanisation"]'::jsonb, 0, 'Intrants et spécialisation pèsent sur les milieux.', 6),
    ('e5ee4a3f-8107-5a93-b8bc-082ddda9b502'::uuid, '5f691160-9e94-52a5-9b3b-5695515b736e'::uuid, 'Qu’est-ce que l’agroécologie ?', 'mcq', '["Une agriculture qui s’appuie sur les fonctionnements naturels pour réduire les intrants","L’agriculture hors-sol","L’agriculture urbaine uniquement","Un label commercial"]'::jsonb, 0, 'Rotation, couverts végétaux, haies, agroforesterie.', 7),
    ('ff63cb92-f019-53c3-b6f7-59ca995f0f34'::uuid, '5f691160-9e94-52a5-9b3b-5695515b736e'::uuid, 'Pourquoi la production agricole mondiale a-t-elle pu tripler depuis 1950 ?', 'mcq', '["Grâce aux rendements, à la mécanisation et à l’irrigation","Grâce à l’augmentation du nombre d’agriculteurs","Grâce à la baisse de la population","Grâce à la réduction des surfaces cultivées"]'::jsonb, 0, 'La révolution verte a transformé les rendements.', 8),
    ('b8bc5643-354e-558c-bec6-30dfafd005ce'::uuid, '7d42b346-c091-5087-8d33-7d6b45d81b18'::uuid, 'Quelles sont les quatre grandes fonctions des espaces ruraux ?', 'mcq', '["Productive, résidentielle, récréative et écologique","Agricole, industrielle, minière et commerciale","Politique, sociale, culturelle et économique","Résidentielle, scolaire, sanitaire et sportive"]'::jsonb, 0, 'Elles se superposent sur les mêmes espaces.', 1),
    ('ea27815c-4042-5307-9157-c72c31d40bd5'::uuid, '7d42b346-c091-5087-8d33-7d6b45d81b18'::uuid, 'Quelle nouvelle activité productive se développe dans les campagnes ?', 'mcq', '["Les énergies renouvelables (éolien, solaire, méthanisation)","La sidérurgie","La construction navale","La pétrochimie"]'::jsonb, 0, 'Elles apportent des revenus mais suscitent des oppositions.', 2),
    ('548408e8-4c80-5178-be54-80a9a45dbfb1'::uuid, '7d42b346-c091-5087-8d33-7d6b45d81b18'::uuid, 'Qu’est-ce qu’un parc naturel régional ?', 'mcq', '["Un territoire habité, protégé et géré par une charte","Une réserve intégrale sans habitants","Un parc d’attractions","Une forêt domaniale"]'::jsonb, 0, 'Il concilie protection, activités et développement local.', 3),
    ('a03b68ac-d97c-5da6-99e2-4e7a903eed65'::uuid, '7d42b346-c091-5087-8d33-7d6b45d81b18'::uuid, 'Qu’est-ce que la trame verte et bleue ?', 'mcq', '["Un réseau de continuités écologiques terrestres et aquatiques","Un plan d’urbanisme","Un label agricole","Un réseau de pistes cyclables"]'::jsonb, 0, 'Elle vise à relier les milieux naturels fragmentés.', 4),
    ('7fb3a26c-f57a-5c9d-a1bb-fa39cfb16985'::uuid, '7d42b346-c091-5087-8d33-7d6b45d81b18'::uuid, 'Le tourisme vert est une fonction récréative des espaces ruraux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Randonnée, gîtes, sports de nature : les citadins y cherchent un cadre de loisirs.', 5),
    ('e3c13259-c64d-5811-9bbd-6bb3735a4b3f'::uuid, '7d42b346-c091-5087-8d33-7d6b45d81b18'::uuid, 'Pourquoi la fonction résidentielle progresse-t-elle dans le rural ?', 'mcq', '["Logement moins cher et cadre de vie recherché","Meilleure desserte en transports en commun","Concentration des services publics","Emplois plus nombreux qu’en ville"]'::jsonb, 0, 'La contrepartie est la dépendance à la voiture.', 6),
    ('5f92a02c-a749-5d7c-8ead-d058deb53a10'::uuid, '7d42b346-c091-5087-8d33-7d6b45d81b18'::uuid, 'Que sont les zones Natura 2000 ?', 'mcq', '["Un réseau européen d’espaces protégés pour la biodiversité","Des zones franches rurales","Des zones agricoles prioritaires","Des zones d’activité économique"]'::jsonb, 0, 'Elles imposent des règles de gestion des habitats et des espèces.', 7),
    ('54bc811a-7815-52eb-8d8b-59daad688ffd'::uuid, '7d42b346-c091-5087-8d33-7d6b45d81b18'::uuid, 'Quand parle-t-on de fragmentation plutôt que de multifonctionnalité ?', 'mcq', '["Quand les fonctions s’excluent et entrent en conflit sur le même espace","Quand elles se complètent","Quand la population augmente","Quand l’agriculture domine"]'::jsonb, 0, 'C’est l’alternative posée par l’intitulé du chapitre.', 8),
    ('26c1953d-a9c7-5417-82fc-143d0175ec1a'::uuid, 'f7c9889c-37f8-543e-8228-ead6da3052d1'::uuid, 'Qu’est-ce qu’un conflit d’usage ?', 'mcq', '["Une opposition entre acteurs qui veulent utiliser différemment le même espace","Un litige entre voisins","Un désaccord sur un prix agricole","Une grève des agriculteurs"]'::jsonb, 0, 'Il naît de la multifonctionnalité des espaces ruraux.', 1),
    ('12c4cd5b-53d9-53db-8104-80b567ef2bf9'::uuid, 'f7c9889c-37f8-543e-8228-ead6da3052d1'::uuid, 'Quel projet d’aéroport a été abandonné en 2018 après une longue mobilisation ?', 'mcq', '["Notre-Dame-des-Landes","Roissy Terminal 4","Toulouse-Francazal","Nantes-Atlantique"]'::jsonb, 0, 'Il est devenu un symbole des conflits d’aménagement.', 2),
    ('d85e53ba-5198-5c41-b9f6-e56e46808a44'::uuid, 'f7c9889c-37f8-543e-8228-ead6da3052d1'::uuid, 'Que signifie l’objectif ZAN ?', 'mcq', '["Zéro artificialisation nette","Zone agricole naturelle","Zone d’aménagement négocié","Zéro azote agricole"]'::jsonb, 0, 'Fixé par la loi Climat et résilience de 2021 à l’horizon 2050.', 3),
    ('b7a10dd3-b69b-54b8-b779-97e49ce3a9a5'::uuid, 'f7c9889c-37f8-543e-8228-ead6da3052d1'::uuid, 'À quoi sert un PLU ?', 'mcq', '["À fixer les règles d’utilisation des sols d’une commune","À protéger les monuments historiques","À gérer les aides agricoles","À organiser les transports scolaires"]'::jsonb, 0, 'Le SCoT joue le même rôle à l’échelle intercommunale.', 4),
    ('0cd97b4d-1036-53ca-bdcf-015eaa94b5a3'::uuid, 'f7c9889c-37f8-543e-8228-ead6da3052d1'::uuid, 'Qu’est-ce qu’une SAFER ?', 'mcq', '["Un organisme qui régule le marché du foncier agricole","Une coopérative de vente","Un syndicat agricole","Une agence de l’eau"]'::jsonb, 0, 'Elle peut préempter pour éviter la spéculation et installer des jeunes agriculteurs.', 5),
    ('1883bf97-e56e-54d3-9c11-7820a937540c'::uuid, 'f7c9889c-37f8-543e-8228-ead6da3052d1'::uuid, 'Les projets d’éoliennes font consensus dans les campagnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils opposent souvent revenus locaux, paysage et riverains.', 6),
    ('3f19f31e-85fe-5a19-bc63-73a83dd5de14'::uuid, 'f7c9889c-37f8-543e-8228-ead6da3052d1'::uuid, 'Qu’est-ce qu’une méga-bassine ?', 'mcq', '["Une grande retenue d’eau pour l’irrigation, objet de contestations","Un bassin de rétention urbain","Un lac artificiel touristique","Une station d’épuration"]'::jsonb, 0, 'Elle cristallise les conflits sur le partage de l’eau.', 7),
    ('5dd0ab9c-067c-5d62-a8fb-080bdaf025a0'::uuid, 'f7c9889c-37f8-543e-8228-ead6da3052d1'::uuid, 'Pourquoi l’artificialisation des sols pose-t-elle problème ?', 'mcq', '["Elle réduit les terres agricoles, imperméabilise et fragmente les milieux","Elle augmente les rendements","Elle protège la biodiversité","Elle limite les inondations"]'::jsonb, 0, 'L’imperméabilisation aggrave au contraire le ruissellement.', 8),
