    ('5e83c766-6dbd-5cf6-97ec-88aa518ed78a'::uuid, 'a526fe01-cc80-5f33-a732-7fa166fbe990'::uuid, 'Qu’est-ce qu’une économie résidentielle ?', 'mcq', '["Une économie qui vit des revenus des habitants et des visiteurs plutôt que de la production locale","Une économie fondée sur le bâtiment","Une économie agricole","Une économie industrielle"]'::jsonb, 0, 'Retraites, salaires venus d’ailleurs et tourisme la font vivre.', 2),
    ('7ab8735b-4c1f-5870-a377-0f4ad4e8e36c'::uuid, 'a526fe01-cc80-5f33-a732-7fa166fbe990'::uuid, 'Qu’est-ce qu’un désert médical ?', 'mcq', '["Un territoire où l’accès aux soins est très difficile faute de professionnels","Une zone sans hôpital public","Une région aride","Un territoire sans pharmacie"]'::jsonb, 0, 'Il concerne aussi certaines périphéries urbaines.', 3),
    ('c8d3975e-7181-57f4-90e0-ea0c4e85305e'::uuid, 'a526fe01-cc80-5f33-a732-7fa166fbe990'::uuid, 'Quel espace français cumule vieillissement et recul des services ?', 'mcq', '["La diagonale des faibles densités","Le littoral atlantique","La couronne parisienne","La vallée du Rhône"]'::jsonb, 0, 'Elle traverse la France du Nord-Est au Sud-Ouest.', 4),
    ('2b28b198-4d04-556b-a1a6-5f8e62ac0e0b'::uuid, 'a526fe01-cc80-5f33-a732-7fa166fbe990'::uuid, 'La voiture est indispensable dans la plupart des espaces ruraux français.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La dépendance automobile donne une portée sociale directe au prix des carburants.', 5),
    ('6f75462a-ca5e-5b81-ac97-d642f23a81f7'::uuid, 'a526fe01-cc80-5f33-a732-7fa166fbe990'::uuid, 'Quelles productions agricoles dominent dans certains DROM ?', 'mcq', '["La banane et la canne à sucre","Le blé et le colza","La betterave et la pomme de terre","Le maïs et le tournesol"]'::jsonb, 0, 'Ces cultures d’exportation structurent leurs espaces ruraux.', 6),
    ('0b6c65b2-409b-51ae-a802-def29e9a0aac'::uuid, 'a526fe01-cc80-5f33-a732-7fa166fbe990'::uuid, 'Quel mouvement social de 2018 a mis en lumière les mobilités rurales ?', 'mcq', '["Les gilets jaunes","Nuit debout","Les bonnets rouges","La jacquerie agricole"]'::jsonb, 0, 'Il est parti d’une taxe sur les carburants.', 7),
    ('93b229d7-c1e0-5ff7-8905-7790efc3d4e9'::uuid, 'a526fe01-cc80-5f33-a732-7fa166fbe990'::uuid, 'Quel est le principal effet de la périurbanisation sur les terres agricoles ?', 'mcq', '["Elle les réduit par l’artificialisation","Elle les protège","Elle les rend plus productives","Elle n’a aucun effet"]'::jsonb, 0, 'Des milliers d’hectares disparaissent chaque année.', 8),
    ('3e42cca8-495c-5cd6-b6b1-8ab0b56e1ce7'::uuid, '323149a4-edbe-5580-ad0d-b0296af6c185'::uuid, 'Quel programme européen finance des projets de développement rural ?', 'mcq', '["LEADER, dans le second pilier de la PAC","Erasmus","Horizon Europe","Le FEDER uniquement"]'::jsonb, 0, 'Il soutient des initiatives portées par des acteurs locaux.', 1),
    ('338a805f-b460-59fc-b98c-cd1ea2545df4'::uuid, '323149a4-edbe-5580-ad0d-b0296af6c185'::uuid, 'Que finance le premier pilier de la PAC ?', 'mcq', '["Les aides directes au revenu des agriculteurs","La recherche agronomique","Les routes rurales","Le tourisme vert"]'::jsonb, 0, 'Le second pilier concerne le développement rural.', 2),
    ('b19896cd-8206-5341-9600-2eb1c493c981'::uuid, '323149a4-edbe-5580-ad0d-b0296af6c185'::uuid, 'Qu’est-ce qu’une AMAP ?', 'mcq', '["Une association qui lie consommateurs et producteurs par des paniers réguliers","Une aide agricole européenne","Un syndicat agricole","Un label de qualité"]'::jsonb, 0, 'C’est une forme de circuit court.', 3),
    ('8ea5f32b-bcde-5d55-939f-459a856fcadf'::uuid, '323149a4-edbe-5580-ad0d-b0296af6c185'::uuid, 'Qu’est-ce qu’un tiers-lieu ?', 'mcq', '["Un espace partagé de travail, de formation ou de création","Une résidence secondaire","Un bâtiment agricole","Une salle des fêtes communale"]'::jsonb, 0, 'Les tiers-lieux ruraux accompagnent le télétravail.', 4),
    ('b19d68f6-b488-59a8-ae2a-5da2bce27177'::uuid, '323149a4-edbe-5580-ad0d-b0296af6c185'::uuid, 'Quel plan a étendu le très haut débit aux campagnes françaises ?', 'mcq', '["Le plan France Très Haut Débit","Le plan Marshall","Le plan Borloo","Le plan Rural 2020"]'::jsonb, 0, 'La couverture numérique est une condition de l’attractivité rurale.', 5),
    ('268e7c8a-f477-506d-a7fb-6f101145917f'::uuid, '323149a4-edbe-5580-ad0d-b0296af6c185'::uuid, 'Les régions gèrent une partie des fonds européens destinés aux territoires.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles sont autorités de gestion pour plusieurs programmes.', 6),
    ('a296e722-2f27-5c14-8325-8bd99eee906a'::uuid, '323149a4-edbe-5580-ad0d-b0296af6c185'::uuid, 'Qu’est-ce qu’une maison de santé pluriprofessionnelle ?', 'mcq', '["Un lieu regroupant plusieurs professionnels de santé pour maintenir l’offre de soins","Un hôpital de proximité","Une pharmacie mutualisée","Un centre thermal"]'::jsonb, 0, 'C’est une réponse fréquente aux déserts médicaux.', 7),
    ('4e8fc6ec-89f9-590e-bc12-5fd41cb23f45'::uuid, '323149a4-edbe-5580-ad0d-b0296af6c185'::uuid, 'Quel est le principal débat de l’aménagement rural ?', 'mcq', '["Concentrer les moyens sur les territoires en difficulté ou soutenir les dynamiques qui marchent","Supprimer ou non la PAC","Fermer ou non les écoles","Développer ou non le tourisme"]'::jsonb, 0, 'C’est un arbitrage politique entre équité et efficacité.', 8),
    ('59032ac8-c8ea-5c39-b710-ac01733f32ab'::uuid, '7ab6e32f-ea3b-513b-a46d-464ffeaa9c91'::uuid, 'Qui lance les réformes économiques chinoises à partir de 1978 ?', 'mcq', '["Deng Xiaoping","Mao Zedong","Xi Jinping","Zhou Enlai"]'::jsonb, 0, 'Le « socialisme de marché » ouvre le pays aux investissements.', 1),
    ('9eac9fa3-46ab-562b-84cd-9136b7334a18'::uuid, '7ab6e32f-ea3b-513b-a46d-464ffeaa9c91'::uuid, 'Quelle ville est la ZES emblématique de l’ouverture chinoise ?', 'mcq', '["Shenzhen","Pékin","Chengdu","Harbin"]'::jsonb, 0, 'Village de pêcheurs en 1980, métropole technologique aujourd’hui.', 2),
    ('f486a5ed-1e5f-5ce7-8a01-ec8f3d9648fa'::uuid, '7ab6e32f-ea3b-513b-a46d-464ffeaa9c91'::uuid, 'En quelle année la Chine entre-t-elle à l’OMC ?', 'mcq', '["2001","1978","1989","2010"]'::jsonb, 0, 'Son intégration au commerce mondial s’accélère alors fortement.', 3),
    ('d1810aa8-88f7-59c4-8dcc-f1493a0d7e72'::uuid, '7ab6e32f-ea3b-513b-a46d-464ffeaa9c91'::uuid, 'Qu’est-ce que le hukou ?', 'mcq', '["Un permis de résidence qui rattache un habitant à sa région d’origine","Un impôt local","Un plan quinquennal","Une zone franche"]'::jsonb, 0, 'Il limite l’accès aux droits sociaux des migrants dans les villes.', 4),
