    ('a6390bd2-3f08-5ee2-bb66-b37aadd72fc0'::uuid, 'c2683946-67f8-55c1-a992-ca9ff0b2172c'::uuid, 'La taxe agricole chinoise a été supprimée en 2006.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’une des mesures visant à réduire l’écart ville-campagne.', 6),
