    ('18cfad2a-fc3d-5598-a762-1564177ddab5'::uuid, 'c2683946-67f8-55c1-a992-ca9ff0b2172c'::uuid, 'L’écart de revenu entre villes et campagnes chinoises a-t-il disparu ?', 'mcq', '["Non, il reste important","Oui, depuis 2010","Oui, depuis 2020","Il s’est inversé"]'::jsonb, 0, 'La réduction des inégalités reste un objectif affiché du pouvoir.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('histoire-geo');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('histoire-geo')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 245 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 245 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
